payload.text:
To implement the **Settings Management** feature, I will create a centralized place to manage the store's profile, preferences, and receipt configurations.

Here is the plan:
1.  **`types.ts`**: Define the `StoreSettings` interface to capture Store Name, Contact Info, Tax settings, and Receipt text.
2.  **`constants.ts`**: Define the default `INITIAL_STORE_SETTINGS`.
3.  **`components/Layout.tsx`**: Enable the **Settings** menu item in the sidebar (previously commented out or disabled).
4.  **`components/Settings.tsx`**: Create a new component with a form to edit and save these configurations.
5.  **`components/POS.tsx`**: Update the **Receipt Printing** logic to use the dynamic store information (Name, Address, Phone) from settings instead of hardcoded values.
6.  **`App.tsx`**: Manage the `storeSettings` state, persist it to local storage, and pass it to the relevant components.

# Updated files:

## types.ts

Added `StoreSettings` interface.

```typescript
export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  email: string;
  avatar?: string;
}

export interface ToastMessage {
  id: string;
  message: string;
  type: 'SUCCESS' | 'ERROR' | 'INFO';
}

export interface StoreSettings {
  storeName: string;
  storeAddress: string;
  storePhone: string;
  storeEmail: string;
  taxRate: number; // percentage
  taxName: string; // e.g. "VAT"
  currency: string;
  receiptHeader?: string;
  receiptFooter?: string;
}

export interface Product {
  id: string;
  name: string;
  sku: string;
  price: number;
  cost: number;
  stock: number;
  category: string;
  description?: string;
  imageUrl?: string;
  minStockLevel: number;
  stockExpiryDate?: string;
}

export interface Customer {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  totalSpent: number;
  visitCount: number;
  lastVisit?: number;
  storeCredit: number;
  type: 'MEMBER' | 'WALK_IN';
}

export interface CustomerSegment {
  id: string;
  name: string;
  description?: string;
  criteria: {
    minSpent?: number;
    maxSpent?: number;
    minVisits?: number;
    maxVisits?: number;
    daysSinceLastVisit?: number; // For "At Risk" / Churn calculation
  };
}

export interface CartItem extends Product {
  quantity: number;
}

export interface SaleItem {
  productId: string;
  productName: string;
  quantity: number;
  priceAtSale: number;
  costAtSale: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  items: SaleItem[];
  totalAmount: number;
  totalProfit: number;
  cashierId: string;
  customerId?: string;
  customerName?: string;
  paymentMethod: 'CASH' | 'CARD' | 'DIGITAL' | 'STORE_CREDIT';
  amountTendered?: number;
  change?: number;
}

export interface DashboardStats {
  totalRevenue: number;
  totalProfit: number;
  lowStockCount: number;
  topSellingProduct: string;
}

export type PurchaseOrderStatus = 'PENDING' | 'ORDERED' | 'RECEIVED' | 'CANCELLED';

export interface PurchaseOrderItem {
  productId: string;
  productName: string;
  quantity: number;
  unitCost: number;
}

export interface PurchaseOrder {
  id: string;
  supplier: string;
  status: PurchaseOrderStatus;
  orderDate: number;
  expectedDate?: string;
  items: PurchaseOrderItem[];
  totalCost: number;
}

export type AdjustmentType = 'ADD' | 'REMOVE' | 'SET';

export interface StockAdjustment {
  id: string;
  productId: string;
  productName: string;
  userId: string;
  userName: string;
  timestamp: number;
  type: AdjustmentType;
  quantity: number; // The input amount
  previousStock: number;
  newStock: number;
  reason: string;
  notes?: string;
}

export interface CreditAdjustment {
  id: string;
  customerId: string;
  customerName: string;
  amount: number;
  type: 'ADD' | 'DEDUCT';
  newBalance: number;
  timestamp: number;
  userId: string;
  userName: string;
  reason?: string;
}

export interface ReturnItem {
  productId: string;
  productName: string;
  quantity: number;
  refundAmount: number;
  reason: string;
  restock: boolean;
}

export interface ReturnTransaction {
  id: string;
  originalSaleId: string;
  timestamp: number;
  items: ReturnItem[];
  totalRefund: number;
  refundMethod: 'CASH' | 'CARD' | 'DIGITAL' | 'STORE_CREDIT';
  cashierId: string;
  customerId?: string;
}

export interface HoldTransaction {
  id: string;
  items: CartItem[];
  customer: Customer; // Snapshot of customer at time of hold
  timestamp: number;
  durationMinutes: number;
  expiryTime: number;
  note?: string;
  cashierId: string;
}
```

