                        {/* Divider */}
                        <div className="border-b border-dashed border-gray-400 mb-2"></div>

                        {/* Financials */}
                        <div className="space-y-1 text-right mb-2">
                            <div className="flex justify-between">
                                <span>Subtotal</span>
                                <span>{symbol}{completedSale.totalAmount.toFixed(2)}</span>
                            </div>

                            {storeSettings.taxRate > 0 && (
                                <div className="flex justify-between text-gray-500 text-[10px]">
                                    <span>{storeSettings.taxName} ({storeSettings.taxRate}%) Incl.</span>
                                    <span>{symbol}{(completedSale.totalAmount - (completedSale.totalAmount / (1 + storeSettings.taxRate/100))).toFixed(2)}</span>
                                </div>
                            )}

                            <div className="flex justify-between font-bold text-lg border-t border-black pt-1 mt-1">
                                <span>TOTAL</span>
                                <span>{symbol}{completedSale.totalAmount.toFixed(2)}</span>
                            </div>
                        </div>

                        {/* Payment Details */}
                        <div className="mb-4 pt-1 border-t border-dashed border-gray-400">
                            <div className="flex justify-between font-bold text-sm">
                                <span>Payment Method:</span>
                                <span className="uppercase">{completedSale.paymentMethod.replace('_', ' ')}</span>
                            </div>
                            {completedSale.paymentMethod === 'CASH' && completedSale.amountTendered !== undefined && (
                                <>
                                    <div className="flex justify-between text-xs mt-1">
                                        <span>Cash Tendered:</span>
                                        <span>{symbol}{completedSale.amountTendered.toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-xs">
                                        <span>Change:</span>
                                        <span>{symbol}{completedSale.change?.toFixed(2)}</span>
                                    </div>
