      {/* Returns History Modal */}
      {isReturnsHistoryOpen && (
           <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
               <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-4xl max-h-[85vh] flex flex-col">
                    <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-red-50 dark:bg-red-900/30 rounded-t-xl">
                        <h3 className="font-bold text-red-800 dark:text-red-300 flex items-center">
                            <RotateCcw className="mr-2" size={20}/>
                            Returns History Log
                        </h3>
                        <button onClick={() => setIsReturnsHistoryOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"/></button>
                    </div>

                    <div className="p-4 border-b border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-800">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={16} />
                            <input 
                                type="text"
                                placeholder="Search by Return ID, Sale ID or Customer..."
                                value={returnsSearchTerm}
                                onChange={(e) => setReturnsSearchTerm(e.target.value)}
                                className="w-full pl-9 pr-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-red-500 text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:placeholder-slate-400"
                            />
                        </div>
                    </div>

                    <div className="overflow-y-auto flex-1 p-4 space-y-4">
                         {filteredReturns.length === 0 ? (
                             <div className="text-center py-10 text-slate-400">
                                 <RotateCcw size={48} className="mx-auto mb-2 opacity-20"/>
                                 <p>No returns found.</p>
                             </div>
                         ) : (
                             filteredReturns.map(ret => {
                                 const customerName = customers.find(c => c.id === ret.customerId)?.name || 'Guest / Walk-in';

                                 return (
                                     <div key={ret.id} className="border border-slate-200 dark:border-slate-700 rounded-lg overflow-hidden bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-700/30 transition">
                                         <div className="p-4 flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-50 dark:border-slate-700/50">
                                             <div>
                                                 <div className="flex items-center gap-2 mb-1">
                                                     <span className="font-bold text-slate-800 dark:text-white">Return #{ret.id.split('-')[1]}</span>
                                                     <span className="text-xs text-slate-400 bg-slate-100 dark:bg-slate-700 px-2 py-0.5 rounded-full">
                                                        Sale #{ret.originalSaleId.split('-')[1]}
                                                     </span>
                                                 </div>
                                                 <div className="text-sm text-slate-500 dark:text-slate-400 flex items-center gap-3">
                                                     <span className="flex items-center"><Calendar size={12} className="mr-1"/> {new Date(ret.timestamp).toLocaleDateString()}</span>
                                                     <span className="flex items-center"><UserIcon size={12} className="mr-1"/> {customerName}</span>
                                                 </div>
                                             </div>
                                             <div className="text-right">
                                                 <div className="font-bold text-red-600 dark:text-red-400 text-lg">-{symbol}{ret.totalRefund.toFixed(2)}</div>
                                                 <div className="text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wide">
                                                     Refund via {ret.refundMethod.replace('_', ' ')}
                                                 </div>
                                             </div>
                                         </div>

                                         <div className="p-4 bg-slate-50 dark:bg-slate-800/50">
                                             <p className="text-xs font-bold text-slate-400 uppercase mb-2">Returned Items</p>
                                             <div className="space-y-2">
                                                 {ret.items.map((item, idx) => (
                                                     <div key={idx} className="flex justify-between items-center text-sm">
                                                         <div className="flex-1">
                                                             <span className="font-medium text-slate-700 dark:text-slate-300">{item.productName}</span>
                                                             <span className="text-slate-400 mx-2">x{item.quantity}</span>
                                                         </div>
                                                         <div className="flex items-center gap-4">
                                                             <span className="text-xs px-2 py-0.5 rounded bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 text-slate-500 dark:text-slate-400">
                                                                 Reason: {item.reason}
                                                             </span>
                                                             {item.restock ? (
                                                                 <span className="flex items-center text-xs text-green-600 dark:text-green-400 font-medium">
                                                                     <CheckCircle size={12} className="mr-1"/> Restocked
                                                                 </span>
                                                             ) : (
                                                                 <span className="flex items-center text-xs text-red-500 dark:text-red-400 font-medium">
                                                                     <Trash size={12} className="mr-1"/> Discarded
                                                                 </span>
                                                             )}
                                                             <span className="font-medium text-slate-700 dark:text-slate-300 w-16 text-right">
                                                                 {symbol}{item.refundAmount.toFixed(2)}
                                                             </span>
                                                         </div>
                                                     </div>
                                                 ))}
                                             </div>
                                         </div>
                                     </div>
                                 );
                             })
                         )}
                    </div>
               </div>
           </div>
      )}

      {/* Orders List Modal (Existing) */}
      {isOrdersModalOpen && (
           <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
               <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-3xl max-h-[85vh] flex flex-col">
                    <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                        <h3 className="font-bold text-slate-800 dark:text-white flex items-center">
                            <Receipt className="mr-2 text-slate-500" size={20}/>
                            Recent Sales & Returns
                        </h3>
                        <button onClick={() => setIsOrdersModalOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"/></button>
                    </div>
                    <div className="p-4 bg-slate-50 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700">
                         <input 
                            type="text"
                            placeholder="Search orders by ID or Customer Name..."
                            value={ordersSearch}
                            onChange={(e) => setOrdersSearch(e.target.value)}
                            className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:placeholder-slate-400"
                         />
                    </div>
                    <div className="overflow-y-auto flex-1 p-4 space-y-3">
                         {filteredOrders.length === 0 ? (
                             <div className="text-center py-10 text-slate-400">No sales found.</div>
                         ) : (
                             filteredOrders.map(sale => {
                                 // Calculate Return Stats for this sale
                                 const relatedReturns = returns.filter(r => r.originalSaleId === sale.id);
                                 const totalReturned = relatedReturns.reduce((sum, r) => sum + r.totalRefund, 0);
                                 const netAmount = sale.totalAmount - totalReturned;
                                 const isFullyReturned = netAmount <= 0.01; // tolerance
                                 const hasReturns = totalReturned > 0;

                                 return (
                                     <div key={sale.id} className="border border-slate-200 dark:border-slate-700 rounded-lg p-4 hover:bg-slate-50 dark:hover:bg-slate-700/50 transition bg-white dark:bg-slate-800">
                                         <div className="flex justify-between items-start mb-2">
                                             <div>
                                                 <div className="flex items-center gap-2">
                                                     <span className="font-bold text-slate-700 dark:text-slate-200">#{sale.id.split('-')[1]}</span>
                                                     {hasReturns && (
                                                         <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${isFullyReturned ? 'bg-red-100 dark:bg-red-900/50 text-red-600 dark:text-red-400' : 'bg-orange-100 dark:bg-orange-900/50 text-orange-600 dark:text-orange-400'}`}>
                                                             {isFullyReturned ? 'FULLY RETURNED' : 'PARTIAL RETURN'}
                                                         </span>
                                                     )}
                                                 </div>
                                                 <div className="text-xs text-slate-500 dark:text-slate-400">{new Date(sale.timestamp).toLocaleString()}</div>
                                             </div>
                                             <div className="text-right">
                                                 {hasReturns ? (
                                                     <>
                                                         <div className="text-xs text-slate-400 line-through decoration-slate-400">{symbol}{sale.totalAmount.toFixed(2)}</div>
                                                         <div className="font-bold text-blue-600 dark:text-blue-400">{symbol}{netAmount.toFixed(2)}</div>
                                                         <div className="text-[10px] text-red-500 font-medium">-{symbol}{totalReturned.toFixed(2)} refunded</div>
                                                     </>
                                                 ) : (
                                                     <div className="font-bold text-blue-600 dark:text-blue-400">{symbol}{sale.totalAmount.toFixed(2)}</div>
                                                 )}
                                                 <div className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{sale.paymentMethod.replace('_', ' ')}</div>
                                             </div>
                                         </div>
                                         <div className="text-sm text-slate-600 dark:text-slate-300 mb-3">
                                             {sale.customerName ? (
                                                 <span className="flex items-center"><UserIcon size={12} className="mr-1"/> {sale.customerName}</span>
                                             ) : (
                                                 <span className="italic text-slate-400">Guest Customer</span>
                                             )}
                                         </div>
                                         <div className="flex justify-between items-center pt-2 border-t border-slate-100 dark:border-slate-700">
                                              <span className="text-xs text-slate-500 dark:text-slate-400">{sale.items.length} items</span>
                                              {!isFullyReturned && (
                                                  <button 
                                                    onClick={() => initiateReturn(sale)}
                                                    className="text-xs flex items-center bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 px-3 py-1.5 rounded hover:bg-slate-100 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 transition"
                                                  >
                                                      <RotateCcw size={14} className="mr-1.5"/> Return Items
                                                  </button>
                                              )}
                                              {isFullyReturned && (
                                                  <span className="text-xs text-slate-400 italic">No items available for return</span>
                                              )}
                                         </div>
                                     </div>
                                 );
                             })
                         )}
                    </div>
               </div>
           </div>
      )}

      {/* Return Processing Modal */}
      {isReturnModalOpen && selectedSaleForReturn && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-3xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-red-50 dark:bg-red-900/30 rounded-t-xl">
                      <div>
                          <h3 className="font-bold text-red-800 dark:text-red-300">Process Return</h3>
                          <p className="text-xs text-red-600 dark:text-red-400">Sale #{selectedSaleForReturn.id.split('-')[1]} • {new Date(selectedSaleForReturn.timestamp).toLocaleDateString()}</p>
                      </div>
                      <button onClick={() => setIsReturnModalOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"/></button>
                  </div>

                  {/* Customer Context Bar */}
                  {selectedSaleForReturn.customerId && (
                      <div className="px-4 py-2 bg-slate-50 dark:bg-slate-700/50 border-b border-slate-100 dark:border-slate-700 flex items-center justify-between">
                          <div className="flex items-center text-sm text-slate-700 dark:text-slate-200">
                              <span className="text-slate-500 dark:text-slate-400 mr-2">Linked Customer:</span>
                              <UserIcon size={14} className="mr-1.5"/>
                              <span className="font-medium">{selectedSaleForReturn.customerName}</span>
                          </div>
                          {(() => {
                              const saleCustomer = customers.find(c => c.id === selectedSaleForReturn.customerId);
                              if (saleCustomer?.type === 'MEMBER') {
                                  return (
                                      <span className="flex items-center text-xs font-bold text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded border border-blue-100 dark:border-blue-800">
                                          <Crown size={10} className="mr-1"/> Member
                                      </span>
                                  );
                              } else {
                                  return (
                                      <span className="flex items-center text-xs font-medium text-slate-500 dark:text-slate-400 bg-slate-200 dark:bg-slate-600 px-2 py-0.5 rounded">
                                          <Footprints size={10} className="mr-1"/> Walk-in
                                      </span>
                                  );
                              }
                          })()}
                      </div>
                  )}

                  <div className="p-4 overflow-y-auto flex-1">
                      <table className="w-full text-left text-sm mb-6">
                          <thead>
                              <tr className="text-slate-500 dark:text-slate-400 border-b border-slate-100 dark:border-slate-700">
                                  <th className="pb-2 w-8"></th>
                                  <th className="pb-2">Product</th>
                                  <th className="pb-2 text-right">Sold</th>
                                  <th className="pb-2 text-right">Returned</th>
                                  <th className="pb-2 text-right">Remaining</th>
                                  <th className="pb-2 text-right">Return Qty</th>
                                  <th className="pb-2 text-right">Refund</th>
                              </tr>
                          </thead>
                          <tbody className="divide-y divide-slate-50 dark:divide-slate-700">
                              {selectedSaleForReturn.items.map(item => {
                                  const prevReturned = getPreviouslyReturnedQty(selectedSaleForReturn.id, item.productId);
                                  const remainingQty = item.quantity - prevReturned;
                                  const isFullyReturned = remainingQty <= 0;

                                  const returnState = returnItemsState.find(r => r.id === item.productId);
                                  const isSelected = !!returnState;

                                  return (
                                      <React.Fragment key={item.productId}>
                                          <tr className={`hover:bg-slate-50 dark:hover:bg-slate-700/50 ${isSelected ? 'bg-blue-50/50 dark:bg-blue-900/20' : ''} ${isFullyReturned ? 'opacity-50' : ''}`}>
                                              <td className="py-3 text-center">
                                                  <input 
                                                    type="checkbox"
                                                    checked={isSelected}
                                                    disabled={isFullyReturned}
                                                    onChange={() => toggleReturnItem(item.productId, remainingQty)}
                                                    className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 disabled:cursor-not-allowed"
                                                  />
                                              </td>
                                              <td className="py-3 font-medium text-slate-700 dark:text-slate-200">
                                                  {item.productName}
                                                  {isFullyReturned && <span className="ml-2 text-[10px] bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 px-1.5 py-0.5 rounded">Fully Returned</span>}
                                              </td>
                                              <td className="py-3 text-right text-slate-500 dark:text-slate-400">{item.quantity}</td>
                                              <td className="py-3 text-right text-slate-500 dark:text-slate-400">{prevReturned}</td>
                                              <td className="py-3 text-right font-medium text-slate-700 dark:text-slate-300">{remainingQty}</td>
                                              <td className="py-3 text-right">
                                                  {isSelected && (
                                                      <div className="flex items-center justify-end">
                                                          <button 
                                                              onClick={() => updateReturnQty(item.productId, -1, remainingQty)} 
                                                              className="w-7 h-7 flex items-center justify-center bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-l hover:bg-slate-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-300 transition"
                                                          >
                                                              <Minus size={12}/>
                                                          </button>
                                                          <input 
                                                              type="number"
                                                              min="1"
                                                              max={remainingQty}
                                                              value={returnState.qty === 0 ? '' : returnState.qty}
                                                              onChange={(e) => {
                                                                  const valStr = e.target.value;
                                                                  if (valStr === '') {
                                                                      setReturnItemsState(prev => prev.map(i => {
                                                                          if (i.id === item.productId) {
                                                                              return { ...i, qty: 0 };
                                                                          }
                                                                          return i;
                                                                      }));
                                                                      return;
                                                                  }

                                                                  let val = parseInt(valStr);
                                                                  if (isNaN(val)) val = 0;
                                                                  // Clamp value to remaining qty but allow 0 for typing
                                                                  val = Math.min(val, remainingQty);

                                                                  setReturnItemsState(prev => prev.map(i => {
                                                                      if (i.id === item.productId) {
                                                                          return { ...i, qty: val };
                                                                      }
                                                                      return i;
                                                                  }));
                                                              }}
                                                              onBlur={() => {
                                                                  // If left empty or 0, default to 1
                                                                  if (returnState.qty < 1) {
                                                                       setReturnItemsState(prev => prev.map(i => {
                                                                          if (i.id === item.productId) {
                                                                              return { ...i, qty: 1 };
                                                                          }
                                                                          return i;
                                                                      }));
                                                                  }
                                                              }}
                                                              onFocus={(e) => e.target.select()}
                                                              className="w-12 h-7 text-center border-t border-b border-slate-200 dark:border-slate-600 text-sm font-bold outline-none focus:ring-1 focus:ring-blue-500 focus:z-10 bg-white dark:bg-slate-700 text-slate-900 dark:text-white [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                                                          />
                                                          <button 
                                                              onClick={() => updateReturnQty(item.productId, 1, remainingQty)} 
                                                              className="w-7 h-7 flex items-center justify-center bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-r hover:bg-slate-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-300 transition"
                                                          >
                                                              <Plus size={12}/>
                                                          </button>
                                                      </div>
                                                  )}
                                              </td>
                                              <td className="py-3 text-right font-bold text-slate-800 dark:text-white">
                                                  {isSelected ? `${symbol}${(returnState.qty * item.priceAtSale).toFixed(2)}` : '-'}
                                              </td>
                                          </tr>
                                          {isSelected && (
                                              <tr className="bg-slate-50/50 dark:bg-slate-700/30">
                                                  <td colSpan={7} className="pb-3 px-2">
                                                      <div className="flex space-x-6 ml-12 items-center">
                                                          <div className="flex items-center">
                                                              <input 
                                                                type="checkbox" 
                                                                checked={returnState.restock}
                                                                onChange={(e) => updateReturnField(item.productId, 'restock', e.target.checked)}
                                                                id={`restock-${item.productId}`}
                                                                className="mr-2 w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                                                              />
                                                              <label htmlFor={`restock-${item.productId}`} className="text-sm text-slate-600 dark:text-slate-300 cursor-pointer select-none">Return to Inventory Stock</label>
                                                          </div>
                                                          <div className="flex items-center flex-1 max-w-xs">
                                                              <label className="text-sm text-slate-500 dark:text-slate-400 mr-2 whitespace-nowrap">Reason:</label>
                                                              <select 
                                                                value={returnState.reason}
                                                                onChange={(e) => updateReturnField(item.productId, 'reason', e.target.value)}
                                                                className="w-full text-sm border rounded p-1.5 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none focus:ring-1 focus:ring-blue-500"
                                                              >
                                                                  <option>Changed Mind</option>
                                                                  <option>Defective</option>
                                                                  <option>Damaged</option>
                                                                  <option>Wrong Item</option>
                                                                  <option>Expired</option>
                                                              </select>
                                                          </div>
                                                      </div>
                                                  </td>
                                              </tr>
                                          )}
                                      </React.Fragment>
                                  );
                              })}
                          </tbody>
                      </table>

                      <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-lg space-y-3">
                          <h4 className="text-sm font-bold text-slate-700 dark:text-slate-300">Refund Method</h4>
                          <div className="flex space-x-2">
                              {(() => {
                                  // Logic to determine available refund methods
                                  const saleCustomer = customers.find(c => c.id === selectedSaleForReturn.customerId);
                                  const isMember = saleCustomer?.type === 'MEMBER';

                                  const methods = ['CASH', 'CARD'];
                                  // Only add STORE_CREDIT if customer is a Member
                                  if (isMember) {
                                      methods.push('STORE_CREDIT');
                                  }

                                  return methods.map(m => (
                                      <button
                                        key={m}
                                        onClick={() => setRefundMethod(m as any)}
                                        className={`flex-1 py-2 text-xs font-bold rounded border transition
                                        ${refundMethod === m 
                                            ? 'bg-blue-600 text-white border-blue-600' 
                                            : 'bg-white dark:bg-slate-700 text-slate-500 dark:text-slate-300 border-slate-200 dark:border-slate-600 hover:bg-slate-100 dark:hover:bg-slate-600'}`}
                                      >
                                          {m.replace('_', ' ')}
                                      </button>
                                  ));
                              })()}
                          </div>
                      </div>
