                                                              <select 
                                                                value={returnState.reason}
                                                                onChange={(e) => updateReturnField(item.productId, 'reason', e.target.value)}
                                                                className="w-full text-sm border rounded p-1.5 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none focus:ring-1 focus:ring-blue-500"
                                                              >
                                                                  <option>Changed Mind</option>
                                                                  <option>Defective</option>
                                                                  <option>Damaged</option>
                                                                  <option>Wrong Item</option>
                                                                  <option>Expired</option>
                                                              </select>
                                                          </div>
                                                      </div>
                                                  </td>
                                              </tr>
                                          )}
                                      </React.Fragment>
                                  );
                              })}
                          </tbody>
                      </table>

                      <div className="bg-slate-50 dark:bg-slate-700/50 p-4 rounded-lg space-y-3">
                          <h4 className="text-sm font-bold text-slate-700 dark:text-slate-300">Refund Method</h4>
                          <div className="flex space-x-2">
                              {(() => {
                                  // Logic to determine available refund methods
                                  const saleCustomer = customers.find(c => c.id === selectedSaleForReturn.customerId);
                                  const isMember = saleCustomer?.type === 'MEMBER';

                                  const methods = ['CASH', 'CARD'];
                                  // Only add STORE_CREDIT if customer is a Member
                                  if (isMember) {
                                      methods.push('STORE_CREDIT');
                                  }

                                  return methods.map(m => (
                                      <button
