                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50 rounded-b-xl">
                      <div>
                          <p className="text-xs text-slate-500 dark:text-slate-400 uppercase">Total Refund</p>
