                            disabled={returnItemsState.length === 0}
                            className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow disabled:opacity-50"
                          >
                              Confirm Return
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
});

export default POS;
