    switch (message.type) {
      case 'SUCCESS':
        return 'bg-emerald-600/95 text-white border-emerald-500 shadow-emerald-500/20';
      case 'ERROR':
        return 'bg-red-600/95 text-white border-red-500 shadow-red-500/20';
      case 'INFO':
        return 'bg-blue-600/95 text-white border-blue-500 shadow-blue-500/20';
      default:
        return 'bg-slate-800/95 text-white border-slate-700 shadow-slate-900/20';
    }
  };

  const getIcon = () => {
    switch (message.type) {
      case 'SUCCESS': return <CheckCircle size={20} className="mr-3 shrink-0" />;
      case 'ERROR': return <AlertCircle size={20} className="mr-3 shrink-0" />;
      default: return <Info size={20} className="mr-3 shrink-0" />;
    }
  };

  return (
    <div className={`pointer-events-auto flex items-center pl-6 pr-2 py-2 rounded-full shadow-2xl border backdrop-blur-sm transition-all transform hover:scale-105 animate-in slide-in-from-top-2 fade-in duration-300 ${getStyles()}`}>
      {getIcon()}
      <span className="font-medium text-sm whitespace-nowrap mr-2">{message.message}</span>

      {/* Countdown Timer / Close Button */}
      <div className="relative ml-auto w-8 h-8 flex items-center justify-center shrink-0 group cursor-pointer" onClick={onClose} title="Close">
          <svg className="absolute inset-0 w-full h-full -rotate-90 pointer-events-none" viewBox="0 0 32 32">
             {/* Background Circle */}
             <circle cx="16" cy="16" r="13" stroke="currentColor" strokeWidth="2" fill="none" className="opacity-20" />
             {/* Progress Circle */}
             <circle 
                cx="16" cy="16" r="13" 
                stroke="currentColor" strokeWidth="2" fill="none" 
                strokeDasharray="81.68" /* 2 * PI * 13 */
                strokeDashoffset="0"
                className="opacity-90"
                style={{ animation: 'countdown 3s linear forwards' }} 
             />
          </svg>
          <X size={14} className="relative z-10 transition-transform group-hover:scale-125" />
      </div>

      <style>{`
        @keyframes countdown {
            from { stroke-dashoffset: 0; }
            to { stroke-dashoffset: 81.68; }
        }
      `}</style>
    </div>
  );
};

