        users={users} 
        onLogin={handleLogin} 
        isDarkMode={isDarkMode}
        onToggleTheme={toggleTheme}
      />
    );
  }

  // Floating Notification Handler for a specific hold
  const handleUrgentHoldClick = (holdId: string) => {
      setResumeHoldId(holdId);
      setCurrentView('pos');
      // Note: We don't clear the urgentHolds list here manually; 
      // resuming the hold in POS will remove it from heldTransactions, 
      // causing the useEffect to update urgentHolds automatically.
  };

  return (
    <>
      {/* Floating Notifications Stack - Positioned Top Right to avoid center Toast overlap */}
      {urgentHolds.length > 0 && (
          <div className="fixed top-20 right-4 z-[50] flex flex-col items-end gap-2 w-full max-w-sm pointer-events-none">
              {urgentHolds.slice(0, 3).map(hold => {
