                              <tr key={product.id} className={`hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group ${selectedIds.includes(product.id) ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''} ${!product.isActive ? 'opacity-50 grayscale' : ''}`}>
