                    {activeLogTab === 'ADJUSTMENTS' && (
                        <div className="space-y-4">
                            <table className="w-full text-left">
                                <thead className="bg-white dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400 border-b dark:border-slate-700">
                                    <tr><th className="p-3">Timestamp</th><th className="p-3">Action</th><th className="p-3 text-center">Amount</th><th className="p-3 text-right">Prev</th><th className="p-3 text-right">New</th><th className="p-3">Reason / User</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {stockAdjustments.filter(a => a.productId === selectedProductForInsights.id).sort((a,b) => b.timestamp - a.timestamp).map(a => (
