    localStorage.setItem('nexus_products', JSON.stringify(products));
    localStorage.setItem('nexus_users', JSON.stringify(users));
    localStorage.setItem('nexus_sales', JSON.stringify(sales));
    localStorage.setItem('nexus_purchase_orders', JSON.stringify(purchaseOrders));
    localStorage.setItem('nexus_customers', JSON.stringify(customers));
    localStorage.setItem('nexus_customer_segments', JSON.stringify(segments));
    localStorage.setItem('nexus_stock_adjustments', JSON.stringify(stockAdjustments));
    localStorage.setItem('nexus_returns', JSON.stringify(returns));
    localStorage.setItem('nexus_credit_adjustments', JSON.stringify(creditAdjustments));
    localStorage.setItem('nexus_held_transactions', JSON.stringify(heldTransactions));
    localStorage.setItem('nexus_price_history', JSON.stringify(priceHistory));
  }, [products, users, sales, purchaseOrders, customers, segments, stockAdjustments, returns, creditAdjustments, heldTransactions, priceHistory]);

  // Monitor Urgent Holds
  useEffect(() => {
      const interval = setInterval(() => {
          setTick(t => t + 1); // Force re-render for countdown

          if (heldTransactions.length === 0) {
              setUrgentHolds([]);
              return;
          }

          const now = Date.now();
          // Find ALL holds expiring in less than 5 minutes (300000ms) but not yet expired
          const urgents = heldTransactions
              .filter(h => h.expiryTime > now && (h.expiryTime - now) < 5 * 60 * 1000)
              .sort((a, b) => a.expiryTime - b.expiryTime); // Sort by soonest expiry first

          setUrgentHolds(urgents);
      }, 1000);

      return () => clearInterval(interval);
  }, [heldTransactions]);

  // Handle Role-Based View Access
  useEffect(() => {
    if (currentUser) {
        // Simple redirect if user is on a page they no longer have permission for
    }
  }, [currentUser, currentView]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);

    // Smart Redirect based on permissions
    if (user.permissions.includes('VIEW_DASHBOARD')) setCurrentView('dashboard');
    else if (user.permissions.includes('POS')) setCurrentView('pos');
    else if (user.permissions.includes('MANAGE_INVENTORY')) setCurrentView('inventory');
    else setCurrentView('dashboard'); // Fallback

    showToast(`Access Granted. Welcome back, ${user.name}!`, 'SUCCESS');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    showToast('Logged out successfully. See you soon!', 'INFO');
  };

  const handleNavigate = (view: string) => {
      // Validation Logic: Prevent navigating away from POS if items are in cart
      if (currentView === 'pos' && posHasItems && view !== 'pos') {
          showToast("Active transaction detected. Please Hold or Complete it first.", 'ERROR');
          // Trigger the Hold Modal inside POS to guide the user
          posRef.current?.triggerHold();
          return;
      }
      setCurrentView(view);
  };

  const handleUpdateSettings = (newSettings: StoreSettings) => {
      setStoreSettings(newSettings);
      showToast("Store settings updated successfully.", 'SUCCESS');
  };

  const handleSaleComplete = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => {
        const soldItem = newSale.items.find(i => i.productId === p.id);
        if (soldItem) {
            return { ...p, stock: p.stock - soldItem.quantity };
        }
        return p;
    }));

    if (newSale.customerId) {
      setCustomers(prev => prev.map(c => {
        if (c.id === newSale.customerId) {
          let newCredit = c.storeCredit || 0;
          if (newSale.paymentMethod === 'STORE_CREDIT') {
              // Allows negative balance (Debt)
              newCredit = newCredit - newSale.totalAmount;
          }
          return {
            ...c,
            visitCount: c.visitCount + 1,
            totalSpent: c.totalSpent + newSale.totalAmount,
            lastVisit: newSale.timestamp,
            storeCredit: newCredit
          };
        }
        return c;
      }));
    }
    showToast(`Sale #${newSale.id.split('-')[1]} completed successfully!`, 'SUCCESS');
  };

  const handleProcessReturn = (returnTx: ReturnTransaction) => {
      setReturns(prev => [...prev, returnTx]);
      let restockedCount = 0;
      setProducts(prev => prev.map(p => {
          const returnItem = returnTx.items.find(ri => ri.productId === p.id);
          if (returnItem && returnItem.restock) {
              restockedCount += returnItem.quantity;
              return { ...p, stock: p.stock + returnItem.quantity };
          }
          return p;
      }));

      if (returnTx.customerId) {
          setCustomers(prev => prev.map(c => {
              if (c.id === returnTx.customerId) {
                  const updatedCredit = returnTx.refundMethod === 'STORE_CREDIT' 
                    ? (c.storeCredit || 0) + returnTx.totalRefund 
                    : c.storeCredit;
                  const updatedTotalSpent = Math.max(0, c.totalSpent - returnTx.totalRefund);
                  return { 
                      ...c, 
                      storeCredit: updatedCredit,
                      totalSpent: updatedTotalSpent
                  };
              }
              return c;
          }));
      }

      showToast(`Return processed. ${restockedCount} items restocked.`, 'SUCCESS');
  };

  const handleSaveOrder = (order: PurchaseOrder) => {
    let isNew = false;
    setPurchaseOrders(prev => {
      const existingIndex = prev.findIndex(o => o.id === order.id);
      if (existingIndex >= 0) {
        const newOrders = [...prev];
        newOrders[existingIndex] = order;
        return newOrders;
      }
      isNew = true;
      return [order, ...prev];
    });
    showToast(`Purchase Order ${isNew ? 'created' : 'updated'} successfully.`, 'SUCCESS');
  };

  const handleDeleteOrder = (orderId: string) => {
    setPurchaseOrders(prev => prev.filter(o => o.id !== orderId));
    showToast('Purchase Order deleted.', 'INFO');
  };

  const handleUpdatePOStatus = (orderId: string, newStatus: PurchaseOrderStatus) => {
    let updatedOrder: PurchaseOrder | undefined;

    setPurchaseOrders(prev => {
      const newOrders = prev.map(o => {
          if (o.id === orderId) {
              updatedOrder = { ...o, status: newStatus };
              return updatedOrder;
          }
          return o;
      });
      return newOrders;
    });

    const order = purchaseOrders.find(o => o.id === orderId);
    if (order && newStatus === 'RECEIVED' && order.status !== 'RECEIVED') {
        setProducts(prevProducts => {
            const updatedProducts = [...prevProducts];
            order.items.forEach(item => {
                const productIndex = updatedProducts.findIndex(p => p.id === item.productId);
                if (productIndex >= 0) {
                    updatedProducts[productIndex] = {
                        ...updatedProducts[productIndex],
                        stock: updatedProducts[productIndex].stock + item.quantity
                    };
                }
            });
            return updatedProducts;
        });
        showToast('Inventory stock updated from received order.', 'SUCCESS');
    } else {
        showToast(`Order status updated to ${newStatus}.`, 'SUCCESS');
    }
  };

  const handleAdjustStock = (adjustment: StockAdjustment) => {
      setStockAdjustments(prev => [...prev, adjustment]);
      setProducts(prev => prev.map(p => {
          if (p.id === adjustment.productId) {
              return { ...p, stock: adjustment.newStock };
          }
          return p;
      }));
      showToast(`Stock adjusted for ${adjustment.productName}.`, 'SUCCESS');
  };

  const handleBulkAdjustStock = (adjustments: StockAdjustment[]) => {
      setStockAdjustments(prev => [...prev, ...adjustments]);

      const adjMap = new Map<string, number>();
      adjustments.forEach(a => adjMap.set(a.productId, a.newStock));

      setProducts(prev => prev.map(p => {
          if (adjMap.has(p.id)) {
              return { ...p, stock: adjMap.get(p.id)! };
          }
          return p;
      }));
      showToast(`Bulk updated ${adjustments.length} products.`, 'SUCCESS');
  };

  // Customer Management Handlers
  const handleAddCustomer = (customer: Customer) => {
      setCustomers(prev => [...prev, customer]);
      showToast('Customer profile created.', 'SUCCESS');
  };

  const handleUpdateCustomer = (customer: Customer) => {
      setCustomers(prev => prev.map(c => c.id === customer.id ? customer : c));
      showToast('Customer profile updated.', 'SUCCESS');
  };

  const handleDeleteCustomer = (id: string) => {
      setCustomers(prev => prev.filter(c => c.id !== id));
      showToast('Customer profile deleted.', 'INFO');
  };

  const handleAddSegment = (segment: CustomerSegment) => {
      setSegments(prev => [...prev, segment]);
      showToast('Customer segment created.', 'SUCCESS');
  };

  const handleDeleteSegment = (id: string) => {
      setSegments(prev => prev.filter(s => s.id !== id));
      showToast('Customer segment deleted.', 'INFO');
  };

  const handleAddCreditAdjustment = (adj: CreditAdjustment) => {
      setCreditAdjustments(prev => [...prev, adj]);
      setCustomers(prev => prev.map(c => {
          if (c.id === adj.customerId) {
              return { ...c, storeCredit: adj.newBalance };
          }
          return c;
      }));
      showToast(`Store credit ${adj.type === 'ADD' ? 'added' : 'deducted'} successfully.`, 'SUCCESS');
  }

  // User Management Handlers
  const handleAddUser = (newUser: User) => {
      if (users.find(u => u.email === newUser.email)) {
          showToast('Email already in use.', 'ERROR');
          return;
      }
      setUsers(prev => [...prev, newUser]);
      showToast(`User ${newUser.name} created.`, 'SUCCESS');
  };

  const handleUpdateUser = (updatedUser: User) => {
      setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
      if (currentUser?.id === updatedUser.id) {
          setCurrentUser(updatedUser); // Update active session if editing self
      }
      showToast(`User ${updatedUser.name} updated.`, 'SUCCESS');
  };

  const handleDeleteUser = (userId: string) => {
      setUsers(prev => prev.filter(u => u.id !== userId));
      showToast('User removed.', 'INFO');
  };

  const handleHoldTransaction = (hold: HoldTransaction) => {
      setHeldTransactions(prev => [...prev, hold]);
      setProducts(prev => prev.map(p => {
          const item = hold.items.find(i => i.id === p.id);
          if (item) {
              return { ...p, stock: p.stock - item.quantity };
          }
          return p;
      }));
      showToast('Transaction held successfully.', 'SUCCESS');
  };

  const handleResumeHold = (holdId: string) => {
      const hold = heldTransactions.find(h => h.id === holdId);
      if (hold) {
          setHeldTransactions(prev => prev.filter(h => h.id !== holdId));
          setProducts(prev => prev.map(p => {
              const item = hold.items.find(i => i.id === p.id);
              if (item) {
                  return { ...p, stock: p.stock + item.quantity };
              }
              return p;
          }));
          // Toast is handled in POS component when cart is populated
      }
  };

  const handleVoidHold = (holdId: string) => {
      const hold = heldTransactions.find(h => h.id === holdId);
      if (hold) {
          setHeldTransactions(prev => prev.filter(h => h.id !== holdId));
          setProducts(prev => prev.map(p => {
              const item = hold.items.find(i => i.id === p.id);
              if (item) {
                  return { ...p, stock: p.stock + item.quantity };
              }
              return p;
          }));
          showToast('Hold transaction voided. Stock returned.', 'INFO');
      }
  };

  const handleLogPriceChange = (log: PriceHistory) => {
      setPriceHistory(prev => [...prev, log]);
  };

  // Floating Notification Handler for a specific hold
  const handleUrgentHoldClick = (holdId: string) => {
      setResumeHoldId(holdId);
      setCurrentView('pos');
  };

  return (
    <>
      {/* Root Layout Wrapper */}
      {!currentUser ? (
        <Login 
          users={users} 
          onLogin={handleLogin} 
          isDarkMode={isDarkMode}
          onToggleTheme={toggleTheme}
        />
      ) : (
        <>
          {/* Floating Notifications Stack - Hidden if in POS View to allow POS to handle them locally in fullscreen */}
          {urgentHolds.length > 0 && currentView !== 'pos' && (
              <div className="fixed top-20 right-4 z-[50] flex flex-col items-end gap-2 w-full max-w-sm pointer-events-none">
                  {urgentHolds.slice(0, 3).map(hold => {
                      const diff = Math.max(0, hold.expiryTime - Date.now());
                      const isCritical = diff < 60 * 1000; // Less than 1 minute

                      return (
                      <div 
                        key={hold.id}
                        onClick={() => handleUrgentHoldClick(hold.id)}
                        className={`pointer-events-auto px-4 py-3 rounded-xl shadow-lg flex items-center space-x-3 cursor-pointer transition-all transform hover:scale-105 hover:-translate-x-1 w-auto backdrop-blur-md border border-white/20
                            ${isCritical 
                                ? 'bg-red-500/95 hover:bg-red-600 text-white shadow-red-500/30' 
                                : 'bg-amber-500/95 hover:bg-amber-600 text-white shadow-amber-500/30'}`}
                      >
                          <AlertCircle className={`shrink-0 ${isCritical ? 'animate-pulse' : ''}`} size={20} />
                          <div className="flex flex-col items-start leading-tight">
                              <span className="font-bold text-[10px] uppercase tracking-wider opacity-90">{isCritical ? 'Expiring Now!' : 'Expiring Soon'}</span>
                              <span className="text-xs font-semibold">
                                  {hold.customer.name} • 
                                  {(() => {
                                      const m = Math.floor(diff / 60000);
                                      const s = Math.floor((diff % 60000) / 1000);
                                      return ` ${m}:${s.toString().padStart(2, '0')}`;
                                  })()}
                              </span>
                          </div>
                          <div className="pl-3 border-l border-white/20 flex items-center font-bold text-xs shrink-0">
                              <PlayCircle size={16} className="mr-1"/> Resume
                          </div>
                      </div>
                  )})}

                  {urgentHolds.length > 3 && (
                      <div className="bg-slate-800/90 text-white text-xs px-3 py-1.5 rounded-full backdrop-blur-sm shadow-md flex items-center">
                          <Bell size={12} className="mr-1.5"/> +{urgentHolds.length - 3} more urgent
                      </div>
                  )}
              </div>
          )}

          <Layout 
            currentUser={currentUser} 
            currentView={currentView} 
            onNavigate={handleNavigate} 
            onLogout={handleLogout}
            isDarkMode={isDarkMode}
            onToggleTheme={toggleTheme}
            currency={currency}
            onCurrencyChange={setCurrency}
            storeSettings={storeSettings}
          >
            {currentView === 'dashboard' && (
              <Dashboard 
                sales={sales} 
                products={products} 
                returns={returns}
                currency={currency} 
              />
            )}

            {currentView === 'inventory' && (
              <Inventory 
                products={products} 
                setProducts={setProducts} 
                stockAdjustments={stockAdjustments}
                onAdjustStock={handleAdjustStock}
                onBulkAdjustStock={handleBulkAdjustStock}
                currentUser={currentUser}
                currency={currency}
                showToast={showToast}
                returns={returns}
                customers={customers}
                sales={sales}
                priceHistory={priceHistory}
                onLogPriceChange={handleLogPriceChange}
              />
            )}

            {currentView === 'pos' && (
              <POS 
                ref={posRef}
                products={products} 
                onCompleteSale={handleSaleComplete} 
                currentUser={currentUser} 
                customers={customers}
                onAddCustomer={handleAddCustomer}
                sales={sales}
                returns={returns}
                onProcessReturn={handleProcessReturn}
                heldTransactions={heldTransactions}
                onHoldTransaction={handleHoldTransaction}
                onResumeHold={handleResumeHold}
                onVoidHold={handleVoidHold}
                currency={currency}
                showToast={showToast}
                storeSettings={storeSettings}
                onCartUpdate={setPosHasItems}
                resumeHoldId={resumeHoldId}
                onClearResumeHold={() => setResumeHoldId(null)}
                onUrgentHoldClick={handleUrgentHoldClick}
                urgentHolds={urgentHolds}
                onAddCreditAdjustment={handleAddCreditAdjustment}
              />
            )}

            {currentView === 'sales' && (
              <SalesHistory 
                sales={sales}
                returns={returns}
                users={users}
                customers={customers}
                currency={currency}
              />
            )}

            {currentView === 'customers' && (
              <Customers 
                customers={customers}
                onAddCustomer={handleAddCustomer}
                onUpdateCustomer={handleUpdateCustomer}
                onDeleteCustomer={handleDeleteCustomer}
                sales={sales}
                returns={returns}
                segments={segments}
                onAddSegment={handleAddSegment}
                onDeleteSegment={handleDeleteSegment}
                currentUser={currentUser}
                creditAdjustments={creditAdjustments}
                onAddCreditAdjustment={handleAddCreditAdjustment}
                currency={currency}
              />
            )}

            {currentView === 'purchase-orders' && (
              <PurchaseOrders 
                orders={purchaseOrders} 
                products={products}
                onSaveOrder={handleSaveOrder}
                onUpdateStatus={handleUpdatePOStatus}
                onDeleteOrder={handleDeleteOrder}
                currency={currency}
              />
            )}

            {currentView === 'users' && (
              <UserManagement 
                users={users} 
                onAddUser={handleAddUser}
                onUpdateUser={handleUpdateUser}
                onDeleteUser={handleDeleteUser}
                currentUser={currentUser}
              />
            )}

            {currentView === 'settings' && (
                <Settings 
                    settings={storeSettings}
                    onUpdateSettings={handleUpdateSettings}
                    currency={currency}
                    onCurrencyChange={setCurrency}
                />
            )}
          </Layout>
        </>
      )}

      {/* Toast Container remains mounted at root level for all views EXCEPT POS in fullscreen which uses local one */}
      <ToastContainer toasts={toasts} removeToast={removeToast} />
    </>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock, generateProductDescription } from '../services/geminiService';
import { 
  Plus, Edit2, Trash2, Search, Wand2, X, 
  FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, 
  ArrowUp, ArrowDown, ChevronsUpDown, TrendingUp, 
  TrendingDown, Clock, Sparkles, CheckSquare, 
  Square, Trash, Activity, ShoppingCart, RotateCcw, ClipboardList,
  History, Upload, Image as ImageIcon, Tags, Layers, 
  Barcode, Factory, Truck, Power, ListOrdered, Printer, Grid, ArrowBigUp, ArrowBigDown
} from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';
type LogTab = 'FINANCIAL' | 'SALES' | 'RETURNS' | 'ADJUSTMENTS' | 'PRICE';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedProductForInsights, setSelectedProductForInsights] = useState<Product | null>(null);
  const [activeLogTab, setActiveLogTab] = useState<LogTab>('FINANCIAL');

  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN' | 'EXPIRED'>('ALL');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);

  // Single Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Bulk Operations State
  const [isBulkAdjModalOpen, setIsBulkAdjModalOpen] = useState(false);
  const [bulkAdjValues, setBulkAdjValues] = useState<Record<string, number>>({}); // Stores the "quantity" input for each product
  const [bulkGlobalType, setBulkGlobalType] = useState<AdjustmentType>('ADD');
  const [bulkGlobalReason, setBulkGlobalReason] = useState('Stock Count Correction');

  const [isBarcodeModalOpen, setIsBarcodeModalOpen] = useState(false);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', brand: '', supplier: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false, isActive: true
  });

  const symbol = useMemo(() => {
    switch(currency) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  }, [currency]);

  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const getDaysUntilExpiry = (dateString?: string) => {
    if (!dateString) return null;
    const [year, month, day] = dateString.split('-').map(Number);
    const expiry = new Date(year, month - 1, day);
    const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.barcode?.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
          if (filterStockStatus === 'EXPIRED') filtered = filtered.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0);
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, sortField, sortDirection]);

  const toggleSelectAll = () => {
    if (selectedIds.length === processedProducts.length) setSelectedIds([]);
    else setSelectedIds(processedProducts.map(p => p.id));
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleBulkDelete = () => {
    if (!window.confirm(`Are you sure you want to delete ${selectedIds.length} products?`)) return;
    setProducts(prev => prev.filter(p => !selectedIds.includes(p.id)));
    setSelectedIds([]);
    showToast(`${selectedIds.length} products removed.`, 'INFO');
  };

  const handleOpenBulkAdj = () => {
      // Initialize bulk values with 0 for all selected items
      const initialValues: Record<string, number> = {};
      selectedIds.forEach(id => initialValues[id] = 0);
      setBulkAdjValues(initialValues);
      setBulkGlobalType('ADD');
      setBulkGlobalReason('Stock Count Correction');
      setIsBulkAdjModalOpen(true);
  };

  const handleBulkSubmit = () => {
      const adjustments: StockAdjustment[] = [];

      selectedIds.forEach(id => {
          const product = products.find(p => p.id === id);
          const qty = bulkAdjValues[id] || 0;

          if (product && (qty !== 0 || bulkGlobalType === 'SET')) {
              let newStock = product.stock;
              if (bulkGlobalType === 'ADD') newStock += qty;
              if (bulkGlobalType === 'REMOVE') newStock -= qty;
              if (bulkGlobalType === 'SET') newStock = qty;

              if (newStock >= 0) {
                  adjustments.push({
                      id: `adj-${Date.now()}-${id}`,
                      productId: product.id,
                      productName: product.name,
                      userId: currentUser.id,
                      userName: currentUser.name,
                      timestamp: Date.now(),
                      type: bulkGlobalType,
                      quantity: qty,
                      previousStock: product.stock,
                      newStock: parseFloat(newStock.toFixed(3)),
                      reason: bulkGlobalReason,
                      notes: 'Bulk Adjustment'
                  });
              }
          }
      });

      if (adjustments.length > 0) {
          onBulkAdjustStock(adjustments);
          setIsBulkAdjModalOpen(false);
          setSelectedIds([]); // Clear selection after action
      } else {
          showToast("No valid adjustments to apply.", 'INFO');
      }
  };

  const handleOpenBarcodeModal = () => {
      setIsBarcodeModalOpen(true);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateDescription = async () => {
    if (!formData.name || !formData.category) {
        showToast("Enter name and category first.", "INFO");
        return;
    }
    setIsGeneratingDescription(true);
    try {
        const desc = await generateProductDescription(formData.name, formData.category);
        setFormData(prev => ({ ...prev, description: desc }));
        showToast("Description generated with AI.", "SUCCESS");
    } catch (e) {
        showToast("AI Generation failed.", "ERROR");
    } finally {
        setIsGeneratingDescription(false);
    }
  };

  const handleExport = () => {
      // Create CSV content with BOM for Excel compatibility
      const headers = [
          'System ID',
          'Product Name', 
          'SKU', 
          'Barcode',
          'Category', 
          'Brand',
          'Supplier',
          'Cost Price', 
          'Selling Price', 
          'Margin %', 
          'Current Stock', 
          'Min Stock Level', 
          'Stock Status',
          'Expiry Date',
          'Asset Value', 
          'Retail Value',
          'Units Sold',
          'Units Returned',
          'Total Revenue',
          'Total Refunds',
          'Net Profit'
      ];

      const rows = processedProducts.map(p => {
          const margin = p.price > 0 ? (((p.price - p.cost) / p.price) * 100).toFixed(2) : '0.00';
          const assetValue = (p.cost * p.stock).toFixed(2);
          const retailValue = (p.price * p.stock).toFixed(2);

          let stockStatus = 'In Stock';
          if (p.stock === 0) stockStatus = 'Out of Stock';
          else if (p.stock <= p.minStockLevel) stockStatus = 'Low Stock';
          const daysLeft = getDaysUntilExpiry(p.stockExpiryDate);
          if (daysLeft !== null && daysLeft < 0) stockStatus = 'Expired';

          // Sales & Profit Stats (Aggregating from history)
          let unitsSold = 0;
          let totalRevenue = 0;
          let totalCOGS = 0;

          sales.forEach(sale => {
              const item = sale.items.find(i => i.productId === p.id);
              if (item) {
                  unitsSold += item.quantity;
                  totalRevenue += (item.priceAtSale * item.quantity);
                  totalCOGS += (item.costAtSale * item.quantity);
              }
          });

          let unitsReturned = 0;
          let totalRefunds = 0;
          let totalReturnCost = 0;

          returns.forEach(ret => {
              const item = ret.items.find(i => i.productId === p.id);
              if (item) {
                  unitsReturned += item.quantity;
                  totalRefunds += item.refundAmount;

                  // Look up cost basis from original sale
                  const originalSale = sales.find(s => s.id === ret.originalSaleId);
                  const originalItem = originalSale?.items.find(i => i.productId === p.id);
                  const costBasis = originalItem ? originalItem.costAtSale : p.cost;

                  // Only reduce COGS (via return cost recovery) if item is restocked
                  if (item.restock) {
                      totalReturnCost += (costBasis * item.quantity);
                  }
              }
          });

          const netProfit = (totalRevenue - totalRefunds) - (totalCOGS - totalReturnCost);

          const safeString = (str?: string) => `"${(str || '').replace(/"/g, '""')}"`;

          return [
              safeString(p.id),
              safeString(p.name),
              safeString(p.sku),
              safeString(p.barcode),
              safeString(p.category),
              safeString(p.brand),
              safeString(p.supplier),
              p.cost.toFixed(2),
              p.price.toFixed(2),
              `${margin}%`,
              p.stock,
              p.minStockLevel,
              safeString(stockStatus),
              safeString(p.stockExpiryDate),
              assetValue,
              retailValue,
              unitsSold,
              unitsReturned,
              totalRevenue.toFixed(2),
              totalRefunds.toFixed(2),
              netProfit.toFixed(2)
          ].join(',');
      });

      const csvContent = "\uFEFF" + [headers.join(','), ...rows].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `Inventory_Report_${new Date().toISOString().split('T')[0]}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      showToast("Detailed CSV exported.", "SUCCESS");
  };

  const handleOpenModal = (product?: Product) => {
