                                              <input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-3 pl-8 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" />
                                          </div>
                                      </div>
                                  </div>
                              </div>

                              <div className="col-span-2">
                                  <div className="flex justify-between items-center mb-1.5">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest">Product Description</label>
                                    <button onClick={handleGenerateDescription} disabled={isGeneratingDescription || !formData.name} className="flex items-center gap-1.5 px-2 py-1 bg-purple-100 dark:bg-purple-900/30 rounded text-[10px] font-black uppercase text-purple-600 hover:text-purple-700 disabled:opacity-50 transition">
                                        <Sparkles size={12} className={isGeneratingDescription ? 'animate-spin' : ''}/>
                                        {isGeneratingDescription ? 'Writing...' : 'Write with AI'}
                                    </button>
                                  </div>
                                  <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors h-24 resize-none" placeholder="Provide product details..."></textarea>
                              </div>
                          </div>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50 rounded-b-2xl">
                      <button onClick={() => setIsModalOpen(false)} className="px-6 py-2.5 text-sm font-bold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 transition">Discard</button>
                      <button onClick={handleSave} className="px-12 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-black shadow-lg shadow-blue-500/20 transition-all transform hover:-translate-y-0.5 active:translate-y-0">
                          {editingProduct ? 'Update Product' : 'Create Product'}
                      </button>
                  </div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-[120] flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col md:flex-row animate-in zoom-in-95 duration-200">
                  {/* Left Side: Context History */}
                  <div className="w-full md:w-80 bg-slate-50 dark:bg-slate-900/50 p-6 border-r border-slate-100 dark:border-slate-700 hidden md:block overflow-y-auto">
                      <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4 flex items-center gap-2"><History size={14}/> Recent Adjustments</h4>
                      <div className="space-y-4">
                          {stockAdjustments.filter(a => a.productId === selectedProductForAdj.id).slice(0, 5).sort((a,b) => b.timestamp - a.timestamp).map(a => (
                              <div key={a.id} className="bg-white dark:bg-slate-800 p-3 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                  <div className="flex justify-between items-start mb-1">
                                      <span className={`text-[9px] font-black uppercase px-1.5 py-0.5 rounded ${a.type === 'ADD' ? 'bg-green-100 text-green-700' : a.type === 'REMOVE' ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-700'}`}>{a.type}</span>
                                      <span className="text-[9px] text-slate-400">{new Date(a.timestamp).toLocaleDateString()}</span>
                                  </div>
                                  <p className="text-xs font-bold text-slate-800 dark:text-white">Qty: {a.type === 'ADD' ? '+' : a.type === 'REMOVE' ? '-' : ''}{a.quantity}</p>
                                  <p className="text-[10px] text-slate-500 mt-1 italic leading-tight">"{a.reason}"</p>
                              </div>
                          ))}
                          {stockAdjustments.filter(a => a.productId === selectedProductForAdj.id).length === 0 && (
                              <div className="text-center py-8 text-slate-400 italic text-xs">No prior adjustments.</div>
                          )}
                      </div>
                  </div>

                  {/* Right Side: Form */}
                  <div className="flex-1 p-8 relative">
                      <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -translate-y-12 translate-x-12 blur-2xl pointer-events-none"></div>
                      <div className="flex justify-between items-start mb-6">
                        <div>
                            <h3 className="text-2xl font-black text-slate-800 dark:text-white mb-1 flex items-center"><Scale size={28} className="mr-3 text-blue-600"/> Adjust Stock</h3>
                            <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">{selectedProductForAdj.name}</p>
                        </div>
                        <div className="text-right">
                            <span className="text-[10px] font-black uppercase text-slate-400 block">Current Stock</span>
                            <span className="text-2xl font-black text-slate-800 dark:text-white">{selectedProductForAdj.stock} <span className="text-xs font-medium text-slate-400 uppercase">{selectedProductForAdj.unit}</span></span>
                        </div>
                      </div>

                      <div className="space-y-6">
                          <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-xl">
                              {['ADD', 'REMOVE', 'SET'].map(type => (
                                  <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-3 text-xs font-black rounded-lg transition-all ${adjType === type ? 'bg-white dark:bg-slate-600 shadow-md text-blue-600 transform scale-105' : 'text-slate-500 hover:text-slate-700'}`}>{type}</button>
                              ))}
                          </div>

                          <div className="relative">
                            <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity === 0 ? '' : adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-6 text-center text-6xl font-black bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-700 rounded-2xl outline-none focus:border-blue-500 transition-all dark:text-white" autoFocus placeholder="0" onFocus={(e) => e.target.select()}/>
                            <span className="absolute bottom-4 right-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">{selectedProductForAdj.unit}</span>
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              <div className="space-y-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest">Reason <span className="text-red-500">*</span></label>
                                <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-3 border-2 rounded-xl text-sm font-bold bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white outline-none focus:border-blue-500">
                                    <option>Stock Count Correction</option>
                                    <option>Damage / Wastage</option>
                                    <option>Received Shipment</option>
                                    <option>Product Return</option>
                                    <option>Expired Item Removal</option>
                                </select>
                              </div>
                              <div className="space-y-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest">Internal Notes</label>
                                <input type="text" value={adjNotes} onChange={e => setAdjNotes(e.target.value)} className="w-full p-3 border-2 rounded-xl text-sm bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white outline-none focus:border-blue-500" placeholder="Optional details..."/>
                              </div>
                          </div>
                      </div>

                      <div className="mt-10 flex gap-3">
                          <button onClick={() => setIsAdjModalOpen(false)} className="px-8 py-4 text-slate-500 font-bold hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl transition">Cancel</button>
                          <button onClick={handleSubmitAdjustment} className="flex-1 py-4 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-xl shadow-lg shadow-blue-500/20 transition-all transform hover:-translate-y-0.5 flex items-center justify-center gap-2">
                              <CheckSquare size={20}/> Process Stock Update
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock, generateProductDescription } from '../services/geminiService';
import { 
  Plus, Edit2, Trash2, Search, Wand2, X, 
  FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, 
  ArrowUp, ArrowDown, ChevronsUpDown, TrendingUp, 
  TrendingDown, Clock, Sparkles, CheckSquare, 
  Square, Trash, Activity, ShoppingCart, RotateCcw, ClipboardList,
  History, Upload, Image as ImageIcon, Tags, Layers, 
  Barcode, Factory, Truck, Power, ListOrdered, Printer, Grid, ArrowBigUp, ArrowBigDown,
  Calendar, User as UserIcon, AlertCircle
} from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';
type LogTab = 'FINANCIAL' | 'SALES' | 'RETURNS' | 'ADJUSTMENTS' | 'PRICE';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedProductForInsights, setSelectedProductForInsights] = useState<Product | null>(null);
  const [activeLogTab, setActiveLogTab] = useState<LogTab>('FINANCIAL');

  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN' | 'EXPIRED'>('ALL');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);

  // Single Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Bulk Operations State
  const [isBulkAdjModalOpen, setIsBulkAdjModalOpen] = useState(false);
  const [bulkAdjValues, setBulkAdjValues] = useState<Record<string, number>>({}); 
  const [bulkGlobalType, setBulkGlobalType] = useState<AdjustmentType>('ADD');
  const [bulkGlobalReason, setBulkGlobalReason] = useState('Stock Count Correction');

  const [isBarcodeModalOpen, setIsBarcodeModalOpen] = useState(false);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', brand: '', supplier: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false, isActive: true
  });

  const symbol = useMemo(() => {
    switch(currency) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  }, [currency]);

  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const getDaysUntilExpiry = (dateString?: string) => {
    if (!dateString) return null;
    const [year, month, day] = dateString.split('-').map(Number);
    const expiry = new Date(year, month - 1, day);
    const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.barcode?.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
          if (filterStockStatus === 'EXPIRED') filtered = filtered.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0);
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, sortField, sortDirection]);

  const toggleSelectAll = () => {
    if (selectedIds.length === processedProducts.length) setSelectedIds([]);
    else setSelectedIds(processedProducts.map(p => p.id));
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleBulkDelete = () => {
    if (!window.confirm(`Are you sure you want to delete ${selectedIds.length} products?`)) return;
    setProducts(prev => prev.filter(p => !selectedIds.includes(p.id)));
    setSelectedIds([]);
    showToast(`${selectedIds.length} products removed.`, 'INFO');
  };

  const handleOpenBulkAdj = () => {
      const initialValues: Record<string, number> = {};
      selectedIds.forEach(id => initialValues[id] = 0);
      setBulkAdjValues(initialValues);
      setBulkGlobalType('ADD');
      setBulkGlobalReason('Stock Count Correction');
      setIsBulkAdjModalOpen(true);
  };

  const handleBulkSubmit = () => {
      const adjustments: StockAdjustment[] = [];
      selectedIds.forEach(id => {
          const product = products.find(p => p.id === id);
          const qty = bulkAdjValues[id] || 0;
          if (product && (qty !== 0 || bulkGlobalType === 'SET')) {
              let newStock = product.stock;
              if (bulkGlobalType === 'ADD') newStock += qty;
              if (bulkGlobalType === 'REMOVE') newStock -= qty;
              if (bulkGlobalType === 'SET') newStock = qty;
              if (newStock >= 0) {
                  adjustments.push({
                      id: `adj-${Date.now()}-${id}`,
                      productId: product.id,
                      productName: product.name,
                      userId: currentUser.id,
                      userName: currentUser.name,
                      timestamp: Date.now(),
                      type: bulkGlobalType,
                      quantity: qty,
                      previousStock: product.stock,
                      newStock: parseFloat(newStock.toFixed(3)),
                      reason: bulkGlobalReason,
                      notes: 'Bulk Adjustment'
                  });
              }
          }
      });
      if (adjustments.length > 0) {
          onBulkAdjustStock(adjustments);
          setIsBulkAdjModalOpen(false);
          setSelectedIds([]);
      } else {
          showToast("No valid adjustments to apply.", 'INFO');
      }
  };

  const handleOpenBarcodeModal = () => setIsBarcodeModalOpen(true);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateDescription = async () => {
    if (!formData.name || !formData.category) {
        showToast("Enter name and category first.", "INFO");
        return;
    }
    setIsGeneratingDescription(true);
    try {
        const desc = await generateProductDescription(formData.name, formData.category);
        setFormData(prev => ({ ...prev, description: desc }));
        showToast("Description generated with AI.", "SUCCESS");
    } catch (e) {
        showToast("AI Generation failed.", "ERROR");
    } finally {
        setIsGeneratingDescription(false);
    }
  };

  const handleExport = () => {
      const headers = ['System ID','Product Name','SKU','Barcode','Category','Brand','Supplier','Cost Price','Selling Price','Margin %','Current Stock','Min Stock Level','Stock Status','Expiry Date','Asset Value','Retail Value','Units Sold','Units Returned','Total Revenue','Total Refunds','Net Profit'];
      const rows = processedProducts.map(p => {
          const margin = p.price > 0 ? (((p.price - p.cost) / p.price) * 100).toFixed(2) : '0.00';
          const assetValue = (p.cost * p.stock).toFixed(2);
          const retailValue = (p.price * p.stock).toFixed(2);
          let stockStatus = 'In Stock';
          if (p.stock === 0) stockStatus = 'Out of Stock';
          else if (p.stock <= p.minStockLevel) stockStatus = 'Low Stock';
          const daysLeft = getDaysUntilExpiry(p.stockExpiryDate);
          if (daysLeft !== null && daysLeft < 0) stockStatus = 'Expired';
          let unitsSold = 0;
          let totalRevenue = 0;
          let totalCOGS = 0;
          sales.forEach(sale => {
              const item = sale.items.find(i => i.productId === p.id);
              if (item) {
                  unitsSold += item.quantity;
                  totalRevenue += (item.priceAtSale * item.quantity);
                  totalCOGS += (item.costAtSale * item.quantity);
              }
          });
          let unitsReturned = 0;
          let totalRefunds = 0;
          let totalReturnCost = 0;
          returns.forEach(ret => {
              const item = ret.items.find(i => i.productId === p.id);
              if (item) {
                  unitsReturned += item.quantity;
                  totalRefunds += item.refundAmount;
                  const originalSale = sales.find(s => s.id === ret.originalSaleId);
                  const originalItem = originalSale?.items.find(i => i.productId === p.id);
                  const costBasis = originalItem ? originalItem.costAtSale : p.cost;
                  if (item.restock) {
                      totalReturnCost += (costBasis * item.quantity);
                  }
              }
          });
          const netProfit = (totalRevenue - totalRefunds) - (totalCOGS - totalReturnCost);
          const safeString = (str?: string) => `"${(str || '').replace(/"/g, '""')}"`;
          return [safeString(p.id),safeString(p.name),safeString(p.sku),safeString(p.barcode),safeString(p.category),safeString(p.brand),safeString(p.supplier),p.cost.toFixed(2),p.price.toFixed(2),`${margin}%`,p.stock,p.minStockLevel,safeString(stockStatus),safeString(p.stockExpiryDate),assetValue,retailValue,unitsSold,unitsReturned,totalRevenue.toFixed(2),totalRefunds.toFixed(2),netProfit.toFixed(2)].join(',');
      });
      const csvContent = "\uFEFF" + [headers.join(','), ...rows].join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `Inventory_Report_${new Date().toISOString().split('T')[0]}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      showToast("Detailed CSV exported.", "SUCCESS");
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', barcode: '', brand: '', supplier: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false, isActive: true }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleOpenInsights = (product: Product) => {
    setSelectedProductForInsights(product);
    setActiveLogTab('FINANCIAL');
  };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== undefined && formData.price !== editingProduct.price) {
          onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      }
      if (formData.cost !== undefined && formData.cost !== editingProduct.cost) {
          onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      }
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
