                                <input type="text" value={adjNotes} onChange={e => setAdjNotes(e.target.value)} className="w-full p-3 border-2 rounded-xl text-sm bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white outline-none focus:border-blue-500" placeholder="Optional details..."/>
                              </div>
                          </div>
                      </div>

                      <div className="mt-10 flex gap-3">
