                  <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-2xl">
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white flex items-center gap-2"><Scale size={20}/> Bulk Stock Adjustment</h3>
                      <button onClick={() => setIsBulkAdjModalOpen(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors"><X size={20}/></button>
                  </div>

