                              <input type="text" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                               <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Unit</label>
                               <input type="text" value={productForm.unit} onChange={e => setProductForm({...productForm, unit: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Selling Price <span className="text-red-500">*</span></label>
                              <input type="number" step="0.01" value={productForm.price} onChange={e => setProductForm({...productForm, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Cost Price</label>
                              <input type="number" step="0.01" value={productForm.cost} onChange={e => setProductForm({...productForm, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Current Stock</label>
                              <input type="number" value={productForm.stock} onChange={e => setProductForm({...productForm, stock: parseInt(e.target.value)})} disabled={!!editingProduct} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white disabled:opacity-50" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Min Stock Level</label>
                              <input type="number" value={productForm.minStockLevel} onChange={e => setProductForm({...productForm, minStockLevel: parseInt(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                           <div className="col-span-2">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Image URL</label>
                              <input type="text" value={productForm.imageUrl} onChange={e => setProductForm({...productForm, imageUrl: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="https://..." />
                          </div>
                          <div className="col-span-2">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1 flex justify-between">
                                  <span>Description</span>
                                  <button onClick={handleGenerateDescription} disabled={isGeneratingDesc} className="text-blue-600 flex items-center hover:underline disabled:opacity-50">
                                      {isGeneratingDesc ? <RefreshCw className="animate-spin mr-1" size={12}/> : <Sparkles size={12} className="mr-1"/>} 
                                      {isGeneratingDesc ? 'Generating...' : 'Generate with AI'}
                                  </button>
                              </label>
                              <textarea rows={3} value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end space-x-3">
                      <button onClick={() => setIsProductModalOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg transition">Cancel</button>
                      <button onClick={handleSaveProduct} className="px-6 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 shadow-md transition">Save Product</button>
                  </div>
