                  <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-lg">
                              <History size={20}/>
                          </div>
                          <div>
                              <h3 className="font-bold text-lg text-slate-800 dark:text-white">Stock History</h3>
                              <p className="text-xs text-slate-500 dark:text-slate-400">{historyProduct.name} ({historyProduct.sku})</p>
                          </div>
                      </div>
                      <button onClick={() => setIsHistoryOpen(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors text-slate-400"><X size={20}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-0">
                      {getProductHistory(historyProduct.id).length === 0 ? (
                          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                              <History size={48} className="opacity-20 mb-4"/>
                              <p className="font-medium">No stock history recorded.</p>
                          </div>
                      ) : (
                          <table className="w-full text-left text-sm border-collapse">
                              <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                  <tr>
                                      <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                      <th className="p-4 border-b dark:border-slate-700">User</th>
                                      <th className="p-4 border-b dark:border-slate-700">Type</th>
                                      <th className="p-4 border-b dark:border-slate-700 text-right">Change</th>
                                      <th className="p-4 border-b dark:border-slate-700 text-center">Stock</th>
                                      <th className="p-4 border-b dark:border-slate-700">Reason / Notes</th>
                                  </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                  {getProductHistory(historyProduct.id).map(adj => (
                                      <tr key={adj.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                          <td className="p-4 text-slate-600 dark:text-slate-300">
                                              <div className="font-medium">{new Date(adj.timestamp).toLocaleDateString()}</div>
                                              <div className="text-xs text-slate-400">{new Date(adj.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                          </td>
                                          <td className="p-4">
                                              <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                  <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                  {adj.userName.split(' ')[0]}
                                              </div>
                                          </td>
                                          <td className="p-4">
                                              <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                                  adj.type === 'ADD' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                                                  adj.type === 'REMOVE' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' :
                                                  'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                                              }`}>
                                                  {adj.type}
                                              </span>
                                          </td>
                                          <td className={`p-4 text-right font-bold ${
                                              adj.type === 'ADD' ? 'text-green-600 dark:text-green-400' : 
                                              adj.type === 'REMOVE' ? 'text-red-600 dark:text-red-400' : 
                                              'text-blue-600 dark:text-blue-400'
                                          }`}>
                                              {adj.type === 'ADD' ? '+' : adj.type === 'REMOVE' ? '-' : ''}{adj.quantity}
                                          </td>
                                          <td className="p-4 text-center">
                                              <div className="flex items-center justify-center gap-2 text-xs">
                                                  <span className="text-slate-400 line-through">{adj.previousStock}</span>
                                                  <ArrowRight size={12} className="text-slate-300"/>
                                                  <span className="font-bold text-slate-800 dark:text-white bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">{adj.newStock}</span>
                                              </div>
                                          </td>
                                          <td className="p-4 max-w-[200px]">
                                              <div className="font-medium text-slate-800 dark:text-white truncate">{adj.reason}</div>
                                              {adj.notes && <div className="text-xs text-slate-500 italic truncate">"{adj.notes}"</div>}
                                          </td>
                                      </tr>
                                  ))}
                              </tbody>
                          </table>
                      )}
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end">
                      <button onClick={() => setIsHistoryOpen(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold rounded-lg hover:bg-slate-300 dark:hover:bg-slate-600 transition">Close</button>
                  </div>
              </div>
          </div>
      )}

      {/* AI Insights Modal */}
      {isInsightsOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-indigo-50 dark:bg-indigo-900/20 rounded-t-xl">
                      <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-300 flex items-center"><Sparkles className="mr-2" size={20}/> Inventory Intelligence</h3>
                      <button onClick={() => setIsInsightsOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={20}/></button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-1">
                      {isLoadingSuggestions ? (
                          <div className="flex flex-col items-center justify-center py-12 text-slate-500">
                              <RefreshCw className="animate-spin mb-3" size={32}/>
                              <p>Analyzing inventory data...</p>
                          </div>
                      ) : (
                          <div className="space-y-4">
                              <h4 className="font-bold text-slate-800 dark:text-white border-b border-slate-100 dark:border-slate-700 pb-2">Restock Recommendations</h4>
                              {restockSuggestions.length === 0 ? (
                                  <p className="text-slate-500 italic">No urgent actions detected. Good job!</p>
                              ) : (
                                  restockSuggestions.map((s, idx) => (
                                      <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-200 dark:border-slate-600">
                                          <span className="font-medium text-slate-800 dark:text-white">{s.productName}</span>
                                          <span className={`px-2 py-1 rounded text-xs font-bold ${s.suggestedAction.includes('Urgent') ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'}`}>
                                              {s.suggestedAction}
                                          </span>
                                      </div>
                                  ))
                              )}
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

    </div>
  );
}

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Product, StockAdjustment, User, ReturnTransaction, Sale, Customer, PriceHistory, UserRole } from '../types';
import { Search, Plus, Filter, Package, AlertTriangle, Edit2, Trash2, Activity, ChevronDown, History, RefreshCw, Save, X, Sparkles, TrendingUp, DollarSign, FileText, ChevronRight, ArrowRight, User as UserIcon } from 'lucide-react';
import { generateProductDescription, suggestRestock } from '../services/geminiService';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

const Inventory: React.FC<InventoryProps> = ({
  products,
  setProducts,
  onAdjustStock,
  onBulkAdjustStock,
  currentUser,
  currency,
  showToast,
  stockAdjustments,
  onLogPriceChange
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Modals
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [isInsightsOpen, setIsInsightsOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [historyProduct, setHistoryProduct] = useState<Product | null>(null);

  // Forms
  const [productForm, setProductForm] = useState<Partial<Product>>({
    name: '', sku: '', category: '', price: 0, cost: 0, stock: 0, minStockLevel: 5, unit: 'pcs', description: '', imageUrl: ''
  });

  const [adjForm, setAdjForm] = useState({
      quantity: 0,
      type: 'ADD' as 'ADD' | 'REMOVE' | 'SET',
      reason: '',
      notes: ''
  });

  // AI State
  const [isGeneratingDesc, setIsGeneratingDesc] = useState(false);
  const [restockSuggestions, setRestockSuggestions] = useState<any[]>([]);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(false);

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };
  const symbol = getCurrencySymbol(currency);

  const categories = ['All', ...Array.from(new Set(products.map(p => p.category))) as string[]];

  const filteredProducts = products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCategory = categoryFilter === 'All' || p.category === categoryFilter;
      return matchSearch && matchCategory;
  });

  const handleOpenModal = (product?: Product) => {
      if (product) {
          setEditingProduct(product);
          setProductForm(product);
      } else {
          setEditingProduct(null);
          setProductForm({ name: '', sku: '', category: 'General', price: 0, cost: 0, stock: 0, minStockLevel: 5, unit: 'pcs', description: '', imageUrl: '' });
      }
      setIsProductModalOpen(true);
  };

  const handleSaveProduct = () => {
      if (!productForm.name || !productForm.sku || productForm.price === undefined) {
          showToast("Name, SKU, and Price are required.", 'ERROR');
          return;
      }

      if (editingProduct) {
          // Check for price change to log history
          if (editingProduct.price !== productForm.price) {
              onLogPriceChange({
                  id: `ph-${Date.now()}`,
                  productId: editingProduct.id,
                  type: 'PRICE',
                  oldValue: editingProduct.price,
                  newValue: productForm.price!,
                  userId: currentUser.id,
                  userName: currentUser.name,
                  timestamp: Date.now()
              });
          }
          if (editingProduct.cost !== productForm.cost) {
              onLogPriceChange({
                  id: `ph-${Date.now()}-c`,
                  productId: editingProduct.id,
                  type: 'COST',
                  oldValue: editingProduct.cost,
                  newValue: productForm.cost!,
                  userId: currentUser.id,
                  userName: currentUser.name,
                  timestamp: Date.now()
              });
          }

          setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...productForm } as Product : p));
          showToast("Product updated successfully.", 'SUCCESS');
      } else {
          const newProduct: Product = {
              id: `p-${Date.now()}`,
              ...productForm as Product
          };
          setProducts(prev => [...prev, newProduct]);
          showToast("Product created successfully.", 'SUCCESS');
      }
      setIsProductModalOpen(false);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Are you sure you want to delete this product?")) {
          setProducts(prev => prev.filter(p => p.id !== id));
          showToast("Product deleted.", 'INFO');
      }
  };

  const handleOpenAdjModal = (product: Product) => {
      setSelectedProduct(product);
      setAdjForm({ quantity: 0, type: 'ADD', reason: '', notes: '' });
      setIsAdjModalOpen(true);
  };

  const handleOpenHistory = (product: Product) => {
      setHistoryProduct(product);
      setIsHistoryOpen(true);
  };

  const handleSubmitAdjustment = () => {
      if (!selectedProduct || adjForm.quantity < 0) return; // Allow 0 for SET, but usually checks > 0

      let newStock = selectedProduct.stock;
      if (adjForm.type === 'ADD') newStock += adjForm.quantity;
      if (adjForm.type === 'REMOVE') newStock = Math.max(0, newStock - adjForm.quantity);
      if (adjForm.type === 'SET') newStock = adjForm.quantity;

      onAdjustStock({
          id: `adj-${Date.now()}`,
          productId: selectedProduct.id,
          productName: selectedProduct.name,
          userId: currentUser.id,
          userName: currentUser.name,
          timestamp: Date.now(),
          type: adjForm.type,
          quantity: adjForm.quantity,
          previousStock: selectedProduct.stock,
          newStock,
          reason: adjForm.reason || 'Manual Adjustment',
          notes: adjForm.notes
      });
      setIsAdjModalOpen(false);
  };

  const handleGenerateDescription = async () => {
      if (!productForm.name || !productForm.category) {
          showToast("Please enter product name and category first.", 'ERROR');
          return;
      }
      setIsGeneratingDesc(true);
      const desc = await generateProductDescription(productForm.name, productForm.category);
      setProductForm(prev => ({ ...prev, description: desc }));
      setIsGeneratingDesc(false);
  };

  const handleOpenInsights = async () => {
      setIsInsightsOpen(true);
      setIsLoadingSuggestions(true);
      const suggestions = await suggestRestock(products);
      setRestockSuggestions(suggestions);
      setIsLoadingSuggestions(false);
  };

  const getProductHistory = (productId: string) => {
      return stockAdjustments
          .filter(a => a.productId === productId)
          .sort((a, b) => b.timestamp - a.timestamp);
  };

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">Inventory</h2>
          <p className="text-slate-500 text-sm mt-1">Manage products, stock levels, and pricing.</p>
        </div>
        <div className="flex space-x-2">
            <button 
              onClick={handleOpenInsights}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg flex items-center transition shadow-sm"
            >
              <Sparkles size={18} className="mr-2" /> AI Insights
            </button>
            <button 
              onClick={() => handleOpenModal()}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center transition shadow-sm"
            >
              <Plus size={18} className="mr-2" /> Add Product
            </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row gap-4 items-center">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="Search products..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400"
            />
          </div>
          <div className="flex items-center space-x-2 w-full md:w-auto">
              <Filter className="text-slate-400" size={20} />
              <select 
                value={categoryFilter}
                onChange={(e) => setCategoryFilter(e.target.value)}
                className="w-full md:w-48 p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white outline-none"
              >
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
          </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
              <tr>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm">Product Name</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm">SKU / Barcode</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm">Category</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-right">Price / Cost</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-right">Margin</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-center">Stock</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                {filteredProducts.length === 0 ? (
                    <tr><td colSpan={7} className="p-8 text-center text-slate-500 dark:text-slate-400">No products found.</td></tr>
                ) : (
                    filteredProducts.map(product => {
                        const margin = product.price > 0 ? ((product.price - product.cost) / product.price) * 100 : 0;
                        const isLow = product.stock <= product.minStockLevel && product.stock > 0;
                        const isOut = product.stock === 0;

                        return (
                            <tr key={product.id} className="border-b border-slate-100 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700/50">
                                <td className="p-4">
                                    <div className="flex items-center">
                                        <div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden shrink-0">
                                            {product.imageUrl ? <img src={product.imageUrl} alt="" className="w-full h-full object-cover"/> : <Package className="w-5 h-5 m-auto text-slate-400"/>}
                                        </div>
                                        <div>
                                            <div className="font-medium text-slate-900 dark:text-white">{product.name}</div>
                                            {product.stockExpiryDate && <div className="text-[10px] text-orange-500">Exp: {product.stockExpiryDate}</div>}
                                        </div>
                                    </div>
                                </td>
                                <td className="p-4">
                                      <div className="text-xs font-mono text-slate-700 dark:text-slate-300 uppercase font-bold">{product.sku}</div>
                                      {product.barcode && <div className="text-[10px] font-mono text-slate-500 dark:text-slate-400">{product.barcode}</div>}
                                </td>
                                <td className="p-4">
                                      <span className="px-2.5 py-1 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700/50 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-600">
                                          {product.category}
                                      </span>
                                </td>
                                <td className="p-4 text-right">
                                      <div className="font-black text-slate-900 dark:text-white">{symbol}{product.price.toFixed(2)}</div>
                                      <div className="text-[10px] font-medium text-slate-500 dark:text-slate-400">Cost: {symbol}{product.cost.toFixed(2)}</div>
                                </td>
                                <td className="p-4 text-right">
                                      <span className={`text-xs font-black px-2 py-1 rounded-lg ${
                                          margin > 40 ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-500/20 dark:text-emerald-400' :
                                          margin > 15 ? 'bg-blue-100 text-blue-800 dark:bg-blue-500/20 dark:text-blue-400' :
                                          'bg-orange-100 text-orange-800 dark:bg-orange-500/20 dark:text-orange-400'
                                      }`}>
                                          {margin.toFixed(1)}%
                                      </span>
                                </td>
                                <td className="p-4 text-center font-black">
                                      <button onClick={() => handleOpenAdjModal(product)} className={`px-2.5 py-1.5 rounded-lg border transition text-xs flex items-center justify-center mx-auto min-w-[70px] ${
                                          isOut ? 'border-red-200 bg-red-50 text-red-700 dark:bg-red-500/20 dark:border-red-900/50 dark:text-red-400' : 
                                          isLow ? 'border-orange-200 bg-orange-50 text-orange-700 dark:bg-orange-500/20 dark:border-orange-900/50 dark:text-orange-400' : 
                                          'border-slate-200 bg-white text-slate-800 hover:bg-slate-50 dark:bg-slate-800 dark:border-slate-600 dark:text-slate-200 dark:hover:bg-slate-700'
                                      }`}>
                                          {product.stock} <span className="text-[9px] font-normal opacity-60 uppercase ml-1">{product.unit}</span>
                                      </button>
                                </td>
                                <td className="p-4 text-right">
                                      <div className="flex items-center justify-end space-x-1">
                                          <button onClick={() => handleOpenHistory(product)} className="p-2 text-indigo-600 hover:bg-indigo-50 dark:text-indigo-400 dark:hover:bg-indigo-900/30 rounded-lg" title="Stock History"><History size={16}/></button>
                                          <button onClick={() => handleOpenModal(product)} className="p-2 text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg" title="Edit"><Edit2 size={16}/></button>
                                          <button onClick={() => handleDelete(product.id)} className="p-2 text-red-500 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/30 rounded-lg" title="Delete"><Trash2 size={16}/></button>
                                      </div>
                                </td>
                            </tr>
                        );
                    })
                )}
            </tbody>
          </table>
      </div>

      {/* Add/Edit Product Modal */}
      {isProductModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center">
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white">{editingProduct ? 'Edit Product' : 'Add New Product'}</h3>
                      <button onClick={() => setIsProductModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={24} /></button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-1 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Product Name <span className="text-red-500">*</span></label>
                              <input type="text" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">SKU <span className="text-red-500">*</span></label>
                              <input type="text" value={productForm.sku} onChange={e => setProductForm({...productForm, sku: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Category</label>
                              <input type="text" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                               <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Unit</label>
                               <input type="text" value={productForm.unit} onChange={e => setProductForm({...productForm, unit: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Selling Price <span className="text-red-500">*</span></label>
                              <input type="number" step="0.01" value={productForm.price} onChange={e => setProductForm({...productForm, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Cost Price</label>
                              <input type="number" step="0.01" value={productForm.cost} onChange={e => setProductForm({...productForm, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Current Stock</label>
                              <input type="number" value={productForm.stock} onChange={e => setProductForm({...productForm, stock: parseInt(e.target.value)})} disabled={!!editingProduct} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white disabled:opacity-50" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Min Stock Level</label>
                              <input type="number" value={productForm.minStockLevel} onChange={e => setProductForm({...productForm, minStockLevel: parseInt(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                           <div className="col-span-2">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Image URL</label>
                              <input type="text" value={productForm.imageUrl} onChange={e => setProductForm({...productForm, imageUrl: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="https://..." />
                          </div>
                          <div className="col-span-2">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1 flex justify-between">
                                  <span>Description</span>
                                  <button onClick={handleGenerateDescription} disabled={isGeneratingDesc} className="text-blue-600 flex items-center hover:underline disabled:opacity-50">
                                      {isGeneratingDesc ? <RefreshCw className="animate-spin mr-1" size={12}/> : <Sparkles size={12} className="mr-1"/>} 
                                      {isGeneratingDesc ? 'Generating...' : 'Generate with AI'}
                                  </button>
                              </label>
                              <textarea rows={3} value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end space-x-3">
                      <button onClick={() => setIsProductModalOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg transition">Cancel</button>
                      <button onClick={handleSaveProduct} className="px-6 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 shadow-md transition">Save Product</button>
                  </div>
              </div>
          </div>
      )}

      {/* Stock Adjustment Modal */}
      {isAdjModalOpen && selectedProduct && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6 animate-in zoom-in-95 duration-200">
                  <h3 className="text-lg font-bold mb-4 text-slate-800 dark:text-white">Adjust Stock: {selectedProduct.name}</h3>
                  <div className="bg-slate-100 dark:bg-slate-700 p-3 rounded-lg mb-4 text-center">
                      <span className="block text-xs text-slate-500 dark:text-slate-400 uppercase font-bold">Current Stock</span>
                      <span className="text-2xl font-black text-slate-800 dark:text-white">{selectedProduct.stock} {selectedProduct.unit}</span>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Action</label>
                          <div className="flex space-x-2">
                              <button onClick={() => setAdjForm({...adjForm, type: 'ADD'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'ADD' ? 'bg-green-100 border-green-200 text-green-700 dark:bg-green-900/30 dark:border-green-800 dark:text-green-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>ADD</button>
                              <button onClick={() => setAdjForm({...adjForm, type: 'REMOVE'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'REMOVE' ? 'bg-red-100 border-red-200 text-red-700 dark:bg-red-900/30 dark:border-red-800 dark:text-red-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>REMOVE</button>
                              <button onClick={() => setAdjForm({...adjForm, type: 'SET'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'SET' ? 'bg-blue-100 border-blue-200 text-blue-700 dark:bg-blue-900/30 dark:border-blue-800 dark:text-blue-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>SET</button>
                          </div>
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Quantity</label>
                          <input type="number" min="0" value={adjForm.quantity} onChange={e => setAdjForm({...adjForm, quantity: parseInt(e.target.value)})} className="w-full p-2 border rounded-lg text-lg font-bold text-center dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Reason</label>
                          <input type="text" value={adjForm.reason} onChange={e => setAdjForm({...adjForm, reason: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="e.g. Damage, Restock, Count" />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Notes</label>
                          <input type="text" value={adjForm.notes} onChange={e => setAdjForm({...adjForm, notes: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="Optional details..." />
                      </div>
                  </div>
                  <div className="flex justify-end space-x-3 mt-6">
                      <button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">Cancel</button>
                      <button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-slate-900 dark:bg-blue-600 text-white font-bold rounded-lg shadow-md">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {/* History Modal */}
      {isHistoryOpen && historyProduct && (
          <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-3xl max-h-[85vh] flex flex-col animate-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-lg">
                              <History size={20}/>
                          </div>
                          <div>
                              <h3 className="font-bold text-lg text-slate-800 dark:text-white">Stock History</h3>
                              <p className="text-xs text-slate-500 dark:text-slate-400">{historyProduct.name} ({historyProduct.sku})</p>
                          </div>
                      </div>
                      <button onClick={() => setIsHistoryOpen(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors text-slate-400"><X size={20}/></button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-0">
                      {getProductHistory(historyProduct.id).length === 0 ? (
                          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                              <History size={48} className="opacity-20 mb-4"/>
                              <p className="font-medium">No stock history recorded.</p>
                          </div>
                      ) : (
                          <table className="w-full text-left text-sm border-collapse">
                              <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                  <tr>
                                      <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                      <th className="p-4 border-b dark:border-slate-700">User</th>
                                      <th className="p-4 border-b dark:border-slate-700">Type</th>
                                      <th className="p-4 border-b dark:border-slate-700 text-right">Change</th>
                                      <th className="p-4 border-b dark:border-slate-700 text-center">Stock</th>
                                      <th className="p-4 border-b dark:border-slate-700">Reason / Notes</th>
                                  </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                  {getProductHistory(historyProduct.id).map(adj => (
                                      <tr key={adj.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                          <td className="p-4 text-slate-600 dark:text-slate-300">
                                              <div className="font-medium">{new Date(adj.timestamp).toLocaleDateString()}</div>
                                              <div className="text-xs text-slate-400">{new Date(adj.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                          </td>
                                          <td className="p-4">
                                              <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                  <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                  {adj.userName.split(' ')[0]}
                                              </div>
                                          </td>
                                          <td className="p-4">
                                              <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                                  adj.type === 'ADD' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                                                  adj.type === 'REMOVE' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' :
                                                  'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                                              }`}>
                                                  {adj.type}
                                              </span>
                                          </td>
                                          <td className={`p-4 text-right font-bold ${
                                              adj.type === 'ADD' ? 'text-green-600 dark:text-green-400' : 
                                              adj.type === 'REMOVE' ? 'text-red-600 dark:text-red-400' : 
                                              'text-blue-600 dark:text-blue-400'
                                          }`}>
                                              {adj.type === 'ADD' ? '+' : adj.type === 'REMOVE' ? '-' : ''}{adj.quantity}
                                          </td>
                                          <td className="p-4 text-center">
                                              <div className="flex items-center justify-center gap-2 text-xs">
                                                  <span className="text-slate-400 line-through">{adj.previousStock}</span>
                                                  <ArrowRight size={12} className="text-slate-300"/>
                                                  <span className="font-bold text-slate-800 dark:text-white bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">{adj.newStock}</span>
                                              </div>
                                          </td>
                                          <td className="p-4 max-w-[200px]">
                                              <div className="font-medium text-slate-800 dark:text-white truncate">{adj.reason}</div>
                                              {adj.notes && <div className="text-xs text-slate-500 italic truncate">"{adj.notes}"</div>}
                                          </td>
                                      </tr>
                                  ))}
                              </tbody>
                          </table>
                      )}
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end">
                      <button onClick={() => setIsHistoryOpen(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold rounded-lg hover:bg-slate-300 dark:hover:bg-slate-600 transition">Close</button>
                  </div>
              </div>
          </div>
      )}

      {/* AI Insights Modal */}
      {isInsightsOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-indigo-50 dark:bg-indigo-900/20 rounded-t-xl">
                      <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-300 flex items-center"><Sparkles className="mr-2" size={20}/> Inventory Intelligence</h3>
                      <button onClick={() => setIsInsightsOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={20}/></button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-1">
                      {isLoadingSuggestions ? (
                          <div className="flex flex-col items-center justify-center py-12 text-slate-500">
                              <RefreshCw className="animate-spin mb-3" size={32}/>
                              <p>Analyzing inventory data...</p>
                          </div>
                      ) : (
                          <div className="space-y-4">
                              <h4 className="font-bold text-slate-800 dark:text-white border-b border-slate-100 dark:border-slate-700 pb-2">Restock Recommendations</h4>
                              {restockSuggestions.length === 0 ? (
                                  <p className="text-slate-500 italic">No urgent actions detected. Good job!</p>
                              ) : (
                                  restockSuggestions.map((s, idx) => (
                                      <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-200 dark:border-slate-600">
                                          <span className="font-medium text-slate-800 dark:text-white">{s.productName}</span>
                                          <span className={`px-2 py-1 rounded text-xs font-bold ${s.suggestedAction.includes('Urgent') ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'}`}>
                                              {s.suggestedAction}
                                          </span>
                                      </div>
                                  ))
                              )}
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

    </div>
  );
}

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Product, StockAdjustment, User, ReturnTransaction, Sale, Customer, PriceHistory, UserRole } from '../types';
import { Search, Plus, Filter, Package, AlertTriangle, Edit2, Trash2, Activity, ChevronDown, History, RefreshCw, Save, X, Sparkles, TrendingUp, DollarSign, FileText, ChevronRight, ArrowRight, User as UserIcon, Image as ImageIcon, Tag, TrendingDown } from 'lucide-react';
import { generateProductDescription, suggestRestock } from '../services/geminiService';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

const Inventory: React.FC<InventoryProps> = ({
  products,
  setProducts,
  onAdjustStock,
  onBulkAdjustStock,
  currentUser,
  currency,
  showToast,
  stockAdjustments,
  onLogPriceChange,
  priceHistory
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Modals
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [isInsightsOpen, setIsInsightsOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [activeHistoryTab, setActiveHistoryTab] = useState<'STOCK' | 'PRICE'>('STOCK');

  // Dropdown state for category input
  const [showCategoryDropdown, setShowCategoryDropdown] = useState(false);

  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [historyProduct, setHistoryProduct] = useState<Product | null>(null);

  // Forms
  const [productForm, setProductForm] = useState<Partial<Product>>({
    name: '', sku: '', category: '', price: 0, cost: 0, stock: 0, minStockLevel: 5, unit: 'pcs', description: '', imageUrl: ''
  });

  const [adjForm, setAdjForm] = useState({
      quantity: 0,
      type: 'ADD' as 'ADD' | 'REMOVE' | 'SET',
      reason: '',
      notes: ''
  });

  // AI State
  const [isGeneratingDesc, setIsGeneratingDesc] = useState(false);
  const [restockSuggestions, setRestockSuggestions] = useState<any[]>([]);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(false);

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };
  const symbol = getCurrencySymbol(currency);

  const categories = ['All', ...Array.from(new Set(products.map(p => p.category))) as string[]];
  const inputSuggestions = categories.filter(c => c !== 'All').sort();

  const filteredProducts = products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCategory = categoryFilter === 'All' || p.category === categoryFilter;
      return matchSearch && matchCategory;
  });

  const handleOpenModal = (product?: Product) => {
      if (product) {
          setEditingProduct(product);
          setProductForm(product);
      } else {
          setEditingProduct(null);
          setProductForm({ name: '', sku: '', category: 'General', price: 0, cost: 0, stock: 0, minStockLevel: 5, unit: 'pcs', description: '', imageUrl: '' });
      }
      setIsProductModalOpen(true);
      setShowCategoryDropdown(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProductForm(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = () => {
      if (!productForm.name || !productForm.sku || productForm.price === undefined) {
          showToast("Name, SKU, and Price are required.", 'ERROR');
          return;
      }

      if (editingProduct) {
          // Check for price change to log history
          if (editingProduct.price !== productForm.price) {
              onLogPriceChange({
                  id: `ph-${Date.now()}`,
                  productId: editingProduct.id,
                  type: 'PRICE',
                  oldValue: editingProduct.price,
                  newValue: productForm.price!,
                  userId: currentUser.id,
                  userName: currentUser.name,
                  timestamp: Date.now()
              });
          }
          if (editingProduct.cost !== productForm.cost) {
              onLogPriceChange({
                  id: `ph-${Date.now()}-c`,
                  productId: editingProduct.id,
                  type: 'COST',
                  oldValue: editingProduct.cost,
                  newValue: productForm.cost!,
                  userId: currentUser.id,
                  userName: currentUser.name,
                  timestamp: Date.now()
              });
          }

          setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...productForm } as Product : p));
          showToast("Product updated successfully.", 'SUCCESS');
      } else {
          const newProduct: Product = {
              id: `p-${Date.now()}`,
              ...productForm as Product
          };
          setProducts(prev => [...prev, newProduct]);
          showToast("Product created successfully.", 'SUCCESS');
      }
      setIsProductModalOpen(false);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Are you sure you want to delete this product?")) {
          setProducts(prev => prev.filter(p => p.id !== id));
          showToast("Product deleted.", 'INFO');
      }
  };

  const handleOpenAdjModal = (product: Product) => {
      setSelectedProduct(product);
      setAdjForm({ quantity: 0, type: 'ADD', reason: '', notes: '' });
      setIsAdjModalOpen(true);
  };

  const handleOpenHistory = (product: Product) => {
      setHistoryProduct(product);
      setActiveHistoryTab('STOCK');
      setIsHistoryOpen(true);
  };

  const handleSubmitAdjustment = () => {
      if (!selectedProduct || adjForm.quantity < 0) return; // Allow 0 for SET, but usually checks > 0

      let newStock = selectedProduct.stock;
      if (adjForm.type === 'ADD') newStock += adjForm.quantity;
      if (adjForm.type === 'REMOVE') newStock = Math.max(0, newStock - adjForm.quantity);
      if (adjForm.type === 'SET') newStock = adjForm.quantity;

      onAdjustStock({
          id: `adj-${Date.now()}`,
          productId: selectedProduct.id,
          productName: selectedProduct.name,
          userId: currentUser.id,
          userName: currentUser.name,
          timestamp: Date.now(),
          type: adjForm.type,
          quantity: adjForm.quantity,
          previousStock: selectedProduct.stock,
          newStock,
          reason: adjForm.reason || 'Manual Adjustment',
          notes: adjForm.notes
      });
      setIsAdjModalOpen(false);
  };

  const handleGenerateDescription = async () => {
      if (!productForm.name || !productForm.category) {
          showToast("Please enter product name and category first.", 'ERROR');
          return;
      }
      setIsGeneratingDesc(true);
      const desc = await generateProductDescription(productForm.name, productForm.category);
      setProductForm(prev => ({ ...prev, description: desc }));
      setIsGeneratingDesc(false);
  };

  const handleOpenInsights = async () => {
      setIsInsightsOpen(true);
      setIsLoadingSuggestions(true);
      const suggestions = await suggestRestock(products);
      setRestockSuggestions(suggestions);
      setIsLoadingSuggestions(false);
  };

  const getProductHistory = (productId: string) => {
      return stockAdjustments
          .filter(a => a.productId === productId)
          .sort((a, b) => b.timestamp - a.timestamp);
  };

  const getProductPriceHistory = (productId: string) => {
      return priceHistory
          .filter(h => h.productId === productId)
          .sort((a, b) => b.timestamp - a.timestamp);
  };

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">Inventory</h2>
          <p className="text-slate-500 text-sm mt-1">Manage products, stock levels, and pricing.</p>
        </div>
        <div className="flex space-x-2">
            <button 
              onClick={handleOpenInsights}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg flex items-center transition shadow-sm"
            >
              <Sparkles size={18} className="mr-2" /> AI Insights
            </button>
            <button 
              onClick={() => handleOpenModal()}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center transition shadow-sm"
            >
              <Plus size={18} className="mr-2" /> Add Product
            </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row gap-4 items-center">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="Search products..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400"
            />
          </div>
          <div className="flex items-center space-x-2 w-full md:w-auto">
              <Filter className="text-slate-400" size={20} />
              <select 
                value={categoryFilter}
                onChange={(e) => setCategoryFilter(e.target.value)}
                className="w-full md:w-48 p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white outline-none"
              >
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
          </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
              <tr>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm">Product Name</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm">SKU / Barcode</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm">Category</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-right">Price / Cost</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-right">Margin</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-center">Stock</th>
                <th className="p-4 font-semibold text-slate-600 dark:text-slate-300 text-sm text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                {filteredProducts.length === 0 ? (
                    <tr><td colSpan={7} className="p-8 text-center text-slate-500 dark:text-slate-400">No products found.</td></tr>
                ) : (
                    filteredProducts.map(product => {
                        const margin = product.price > 0 ? ((product.price - product.cost) / product.price) * 100 : 0;
                        const isLow = product.stock <= product.minStockLevel && product.stock > 0;
                        const isOut = product.stock === 0;

                        return (
                            <tr key={product.id} className="border-b border-slate-100 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700/50">
                                <td className="p-4">
                                    <div className="flex items-center">
                                        <div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden shrink-0">
                                            {product.imageUrl ? <img src={product.imageUrl} alt="" className="w-full h-full object-cover"/> : <Package className="w-5 h-5 m-auto text-slate-400"/>}
                                        </div>
                                        <div>
                                            <div className="font-medium text-slate-900 dark:text-white">{product.name}</div>
                                            {product.stockExpiryDate && <div className="text-[10px] text-orange-500">Exp: {product.stockExpiryDate}</div>}
                                        </div>
                                    </div>
                                </td>
                                <td className="p-4">
                                      <div className="text-xs font-mono text-slate-700 dark:text-slate-300 uppercase font-bold">{product.sku}</div>
                                      {product.barcode && <div className="text-[10px] font-mono text-slate-500 dark:text-slate-400">{product.barcode}</div>}
                                </td>
                                <td className="p-4">
                                      <span className="px-2.5 py-1 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700/50 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-600">
                                          {product.category}
                                      </span>
                                </td>
                                <td className="p-4 text-right">
                                      <div className="font-black text-slate-900 dark:text-white">{symbol}{product.price.toFixed(2)}</div>
                                      <div className="text-[10px] font-medium text-slate-500 dark:text-slate-400">Cost: {symbol}{product.cost.toFixed(2)}</div>
                                </td>
                                <td className="p-4 text-right">
                                      <span className={`text-xs font-black px-2 py-1 rounded-lg ${
                                          margin > 40 ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-500/20 dark:text-emerald-400' :
                                          margin > 15 ? 'bg-blue-100 text-blue-800 dark:bg-blue-500/20 dark:text-blue-400' :
                                          'bg-orange-100 text-orange-800 dark:bg-orange-500/20 dark:text-orange-400'
                                      }`}>
                                          {margin.toFixed(1)}%
                                      </span>
                                </td>
                                <td className="p-4 text-center font-black">
                                      <button onClick={() => handleOpenAdjModal(product)} className={`px-2.5 py-1.5 rounded-lg border transition text-xs flex items-center justify-center mx-auto min-w-[70px] ${
                                          isOut ? 'border-red-200 bg-red-50 text-red-700 dark:bg-red-500/20 dark:border-red-900/50 dark:text-red-400' : 
                                          isLow ? 'border-orange-200 bg-orange-50 text-orange-700 dark:bg-orange-500/20 dark:border-orange-900/50 dark:text-orange-400' : 
                                          'border-slate-200 bg-white text-slate-800 hover:bg-slate-50 dark:bg-slate-800 dark:border-slate-600 dark:text-slate-200 dark:hover:bg-slate-700'
                                      }`}>
                                          {product.stock} <span className="text-[9px] font-normal opacity-60 uppercase ml-1">{product.unit}</span>
                                      </button>
                                </td>
                                <td className="p-4 text-right">
                                      <div className="flex items-center justify-end space-x-1">
                                          <button onClick={() => handleOpenHistory(product)} className="p-2 text-indigo-600 hover:bg-indigo-50 dark:text-indigo-400 dark:hover:bg-indigo-900/30 rounded-lg" title="Product History"><History size={16}/></button>
                                          <button onClick={() => handleOpenModal(product)} className="p-2 text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg" title="Edit"><Edit2 size={16}/></button>
                                          <button onClick={() => handleDelete(product.id)} className="p-2 text-red-500 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/30 rounded-lg" title="Delete"><Trash2 size={16}/></button>
                                      </div>
                                </td>
                            </tr>
                        );
                    })
                )}
            </tbody>
          </table>
      </div>

      {/* Add/Edit Product Modal */}
      {isProductModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center">
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white">{editingProduct ? 'Edit Product' : 'Add New Product'}</h3>
                      <button onClick={() => setIsProductModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={24} /></button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-1 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Product Name <span className="text-red-500">*</span></label>
                              <input type="text" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">SKU <span className="text-red-500">*</span></label>
                              <input type="text" value={productForm.sku} onChange={e => setProductForm({...productForm, sku: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1 relative group">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Category</label>
                              <div className="relative">
                                  <input 
                                      type="text" 
                                      value={productForm.category} 
                                      onChange={e => {
                                          setProductForm({...productForm, category: e.target.value});
                                          setShowCategoryDropdown(true);
                                      }}
                                      onFocus={() => setShowCategoryDropdown(true)}
                                      onBlur={() => setTimeout(() => setShowCategoryDropdown(false), 200)}
                                      className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                                      placeholder="Select or create..."
                                  />
                                  <div className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                                      <ChevronDown size={14} />
                                  </div>

                                  {showCategoryDropdown && (
                                      <div className="absolute z-20 w-full mt-1 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg shadow-xl max-h-48 overflow-y-auto">
                                          {inputSuggestions
                                              .filter(c => c.toLowerCase().includes((productForm.category || '').toLowerCase()))
                                              .map(c => (
                                              <div 
                                                  key={c}
                                                  onMouseDown={(e) => {
                                                      e.preventDefault();
                                                      setProductForm({...productForm, category: c});
                                                      setShowCategoryDropdown(false);
                                                  }}
                                                  className="px-3 py-2 hover:bg-slate-100 dark:hover:bg-slate-600 cursor-pointer text-sm text-slate-700 dark:text-slate-200"
                                              >
                                                  {c}
                                              </div>
                                          ))}

                                          {productForm.category && !inputSuggestions.some(c => c.toLowerCase() === productForm.category?.toLowerCase()) && (
                                              <div 
                                                  onMouseDown={(e) => {
                                                      e.preventDefault();
                                                      setShowCategoryDropdown(false);
                                                  }}
                                                  className="px-3 py-2 hover:bg-blue-50 dark:hover:bg-blue-900/30 cursor-pointer text-sm text-blue-600 dark:text-blue-400 font-bold border-t border-slate-100 dark:border-slate-600 flex items-center"
                                              >
                                                  <Plus size={14} className="mr-1"/> Create "{productForm.category}"
                                              </div>
                                          )}
                                      </div>
                                  )}
                              </div>
                          </div>
                          <div className="col-span-2 md:col-span-1">
                               <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Unit</label>
                               <input type="text" value={productForm.unit} onChange={e => setProductForm({...productForm, unit: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Selling Price <span className="text-red-500">*</span></label>
                              <input type="number" step="0.01" value={productForm.price} onChange={e => setProductForm({...productForm, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Cost Price</label>
                              <input type="number" step="0.01" value={productForm.cost} onChange={e => setProductForm({...productForm, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Current Stock</label>
                              <input type="number" value={productForm.stock} onChange={e => setProductForm({...productForm, stock: parseInt(e.target.value)})} disabled={!!editingProduct} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white disabled:opacity-50" />
                          </div>
                          <div className="col-span-2 md:col-span-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Min Stock Level</label>
                              <input type="number" value={productForm.minStockLevel} onChange={e => setProductForm({...productForm, minStockLevel: parseInt(e.target.value)})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                           <div className="col-span-2">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-2">Product Image</label>
                              <div className="flex items-start space-x-4">
                                  <div className="relative w-24 h-24 rounded-xl bg-slate-100 dark:bg-slate-700 border-2 border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center overflow-hidden shrink-0 group">
                                      {productForm.imageUrl ? (
                                          <>
                                              <img src={productForm.imageUrl} alt="Preview" className="w-full h-full object-cover" />
                                              <button 
                                                  onClick={() => setProductForm({...productForm, imageUrl: ''})}
                                                  className="absolute inset-0 bg-black/50 text-white opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity"
                                                  title="Remove Image"
                                              >
                                                  <X size={20} />
                                              </button>
                                          </>
                                      ) : (
                                          <div className="flex flex-col items-center text-slate-400">
                                              <ImageIcon size={24} className="mb-1" />
                                              <span className="text-[10px] font-medium">No Image</span>
                                          </div>
                                      )}
                                  </div>
                                  <div className="flex-1 space-y-3">
                                      <div>
                                          <input 
                                              type="file" 
                                              accept="image/*"
                                              onChange={handleImageUpload}
                                              className="block w-full text-xs text-slate-500 dark:text-slate-400
                                                  file:mr-4 file:py-2 file:px-4
                                                  file:rounded-lg file:border-0
                                                  file:text-xs file:font-bold
                                                  file:bg-blue-50 file:text-blue-700
                                                  hover:file:bg-blue-100
                                                  dark:file:bg-blue-900/30 dark:file:text-blue-300
                                                  cursor-pointer"
                                          />
                                      </div>
                                      <div className="relative">
                                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs">URL</span>
                                          <input 
                                              type="text" 
                                              value={productForm.imageUrl} 
                                              onChange={e => setProductForm({...productForm, imageUrl: e.target.value})} 
                                              className="w-full pl-10 p-2 border text-xs rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none" 
                                              placeholder="https://example.com/image.png" 
                                          />
                                      </div>
                                  </div>
                              </div>
                          </div>
                          <div className="col-span-2">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1 flex justify-between">
                                  <span>Description</span>
                                  <button onClick={handleGenerateDescription} disabled={isGeneratingDesc} className="text-blue-600 flex items-center hover:underline disabled:opacity-50">
                                      {isGeneratingDesc ? <RefreshCw className="animate-spin mr-1" size={12}/> : <Sparkles size={12} className="mr-1"/>} 
                                      {isGeneratingDesc ? 'Generating...' : 'Generate with AI'}
                                  </button>
                              </label>
                              <textarea rows={3} value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                          </div>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end space-x-3">
                      <button onClick={() => setIsProductModalOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg transition">Cancel</button>
                      <button onClick={handleSaveProduct} className="px-6 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 shadow-md transition">Save Product</button>
                  </div>
              </div>
          </div>
      )}

      {/* Stock Adjustment Modal */}
      {isAdjModalOpen && selectedProduct && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6 animate-in zoom-in-95 duration-200">
                  <h3 className="text-lg font-bold mb-4 text-slate-800 dark:text-white">Adjust Stock: {selectedProduct.name}</h3>
                  <div className="bg-slate-100 dark:bg-slate-700 p-3 rounded-lg mb-4 text-center">
                      <span className="block text-xs text-slate-500 dark:text-slate-400 uppercase font-bold">Current Stock</span>
                      <span className="text-2xl font-black text-slate-800 dark:text-white">{selectedProduct.stock} {selectedProduct.unit}</span>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Action</label>
                          <div className="flex space-x-2">
                              <button onClick={() => setAdjForm({...adjForm, type: 'ADD'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'ADD' ? 'bg-green-100 border-green-200 text-green-700 dark:bg-green-900/30 dark:border-green-800 dark:text-green-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>ADD</button>
                              <button onClick={() => setAdjForm({...adjForm, type: 'REMOVE'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'REMOVE' ? 'bg-red-100 border-red-200 text-red-700 dark:bg-red-900/30 dark:border-red-800 dark:text-red-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>REMOVE</button>
                              <button onClick={() => setAdjForm({...adjForm, type: 'SET'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'SET' ? 'bg-blue-100 border-blue-200 text-blue-700 dark:bg-blue-900/30 dark:border-blue-800 dark:text-blue-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>SET</button>
                          </div>
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Quantity</label>
                          <input type="number" min="0" value={adjForm.quantity} onChange={e => setAdjForm({...adjForm, quantity: parseInt(e.target.value)})} className="w-full p-2 border rounded-lg text-lg font-bold text-center dark:bg-slate-700 dark:border-slate-600 dark:text-white" />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Reason</label>
                          <input type="text" value={adjForm.reason} onChange={e => setAdjForm({...adjForm, reason: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="e.g. Damage, Restock, Count" />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Notes</label>
                          <input type="text" value={adjForm.notes} onChange={e => setAdjForm({...adjForm, notes: e.target.value})} className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="Optional details..." />
                      </div>
                  </div>
                  <div className="flex justify-end space-x-3 mt-6">
                      <button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">Cancel</button>
                      <button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-slate-900 dark:bg-blue-600 text-white font-bold rounded-lg shadow-md">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {/* History Modal */}
      {isHistoryOpen && historyProduct && (
          <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-3xl max-h-[85vh] flex flex-col animate-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-lg">
                              <History size={20}/>
                          </div>
                          <div>
                              <h3 className="font-bold text-lg text-slate-800 dark:text-white">Product History</h3>
                              <p className="text-xs text-slate-500 dark:text-slate-400">{historyProduct.name} ({historyProduct.sku})</p>
                          </div>
                      </div>
                      <button onClick={() => setIsHistoryOpen(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors text-slate-400"><X size={20}/></button>
                  </div>

                  {/* Tabs */}
                  <div className="flex border-b border-slate-100 dark:border-slate-700 px-5 gap-6">
                      <button 
                        onClick={() => setActiveHistoryTab('STOCK')}
                        className={`py-3 text-sm font-bold border-b-2 transition-colors ${activeHistoryTab === 'STOCK' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
                      >
                          Stock Changes
                      </button>
                      <button 
                        onClick={() => setActiveHistoryTab('PRICE')}
                        className={`py-3 text-sm font-bold border-b-2 transition-colors ${activeHistoryTab === 'PRICE' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
                      >
                          Price History
                      </button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-0">
                      {activeHistoryTab === 'STOCK' ? (
                          getProductHistory(historyProduct.id).length === 0 ? (
                              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                  <History size={48} className="opacity-20 mb-4"/>
                                  <p className="font-medium">No stock history recorded.</p>
                              </div>
                          ) : (
                              <table className="w-full text-left text-sm border-collapse">
                                  <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                      <tr>
                                          <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                          <th className="p-4 border-b dark:border-slate-700">User</th>
                                          <th className="p-4 border-b dark:border-slate-700">Type</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Change</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-center">Stock</th>
                                          <th className="p-4 border-b dark:border-slate-700">Reason / Notes</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                      {getProductHistory(historyProduct.id).map(adj => (
                                          <tr key={adj.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                              <td className="p-4 text-slate-600 dark:text-slate-300">
                                                  <div className="font-medium">{new Date(adj.timestamp).toLocaleDateString()}</div>
                                                  <div className="text-xs text-slate-400">{new Date(adj.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                              </td>
                                              <td className="p-4">
                                                  <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                      <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                      {adj.userName.split(' ')[0]}
                                                  </div>
                                              </td>
                                              <td className="p-4">
                                                  <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                                      adj.type === 'ADD' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                                                      adj.type === 'REMOVE' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' :
                                                      'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                                                  }`}>
                                                      {adj.type}
                                                  </span>
                                              </td>
                                              <td className={`p-4 text-right font-bold ${
                                                  adj.type === 'ADD' ? 'text-green-600 dark:text-green-400' : 
                                                  adj.type === 'REMOVE' ? 'text-red-600 dark:text-red-400' : 
                                                  'text-blue-600 dark:text-blue-400'
                                              }`}>
                                                  {adj.type === 'ADD' ? '+' : adj.type === 'REMOVE' ? '-' : ''}{adj.quantity}
                                              </td>
                                              <td className="p-4 text-center">
                                                  <div className="flex items-center justify-center gap-2 text-xs">
                                                      <span className="text-slate-400 line-through">{adj.previousStock}</span>
                                                      <ArrowRight size={12} className="text-slate-300"/>
                                                      <span className="font-bold text-slate-800 dark:text-white bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">{adj.newStock}</span>
                                                  </div>
                                              </td>
                                              <td className="p-4 max-w-[200px]">
                                                  <div className="font-medium text-slate-800 dark:text-white truncate">{adj.reason}</div>
                                                  {adj.notes && <div className="text-xs text-slate-500 italic truncate">"{adj.notes}"</div>}
                                              </td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          )
                      ) : (
                          getProductPriceHistory(historyProduct.id).length === 0 ? (
                              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                  <Tag size={48} className="opacity-20 mb-4"/>
                                  <p className="font-medium">No price changes recorded.</p>
                              </div>
                          ) : (
                              <table className="w-full text-left text-sm border-collapse">
                                  <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                      <tr>
                                          <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                          <th className="p-4 border-b dark:border-slate-700">User</th>
                                          <th className="p-4 border-b dark:border-slate-700">Change Type</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Old Value</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">New Value</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Diff</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                      {getProductPriceHistory(historyProduct.id).map(log => {
                                          const diff = log.newValue - log.oldValue;
                                          const isIncrease = diff > 0;
                                          return (
                                              <tr key={log.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                                  <td className="p-4 text-slate-600 dark:text-slate-300">
                                                      <div className="font-medium">{new Date(log.timestamp).toLocaleDateString()}</div>
                                                      <div className="text-xs text-slate-400">{new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                                  </td>
                                                  <td className="p-4">
                                                      <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                          <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                          {log.userName.split(' ')[0]}
                                                      </div>
                                                  </td>
                                                  <td className="p-4">
                                                      <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${log.type === 'PRICE' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'}`}>
                                                          {log.type === 'PRICE' ? 'Selling Price' : 'Cost Price'}
                                                      </span>
                                                  </td>
                                                  <td className="p-4 text-right text-slate-500 font-mono">
                                                      {symbol}{log.oldValue.toFixed(2)}
                                                  </td>
                                                  <td className="p-4 text-right font-bold text-slate-800 dark:text-white font-mono">
                                                      {symbol}{log.newValue.toFixed(2)}
                                                  </td>
                                                  <td className="p-4 text-right">
                                                      <div className={`flex items-center justify-end font-bold text-xs ${isIncrease ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                                                          {isIncrease ? <TrendingUp size={14} className="mr-1"/> : <TrendingDown size={14} className="mr-1"/>}
                                                          {Math.abs((diff / log.oldValue) * 100).toFixed(1)}%
                                                      </div>
                                                  </td>
                                              </tr>
                                          );
                                      })}
                                  </tbody>
                              </table>
                          )
                      )}
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end">
                      <button onClick={() => setIsHistoryOpen(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold rounded-lg hover:bg-slate-300 dark:hover:bg-slate-600 transition">Close</button>
                  </div>
              </div>
          </div>
      )}

      {/* AI Insights Modal */}
      {isInsightsOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-indigo-50 dark:bg-indigo-900/20 rounded-t-xl">
                      <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-300 flex items-center"><Sparkles className="mr-2" size={20}/> Inventory Intelligence</h3>
                      <button onClick={() => setIsInsightsOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={20}/></button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-1">
                      {isLoadingSuggestions ? (
                          <div className="flex flex-col items-center justify-center py-12 text-slate-500">
                              <RefreshCw className="animate-spin mb-3" size={32}/>
                              <p>Analyzing inventory data...</p>
                          </div>
                      ) : (
                          <div className="space-y-4">
                              <h4 className="font-bold text-slate-800 dark:text-white border-b border-slate-100 dark:border-slate-700 pb-2">Restock Recommendations</h4>
                              {restockSuggestions.length === 0 ? (
                                  <p className="text-slate-500 italic">No urgent actions detected. Good job!</p>
                              ) : (
                                  restockSuggestions.map((s, idx) => (
                                      <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-200 dark:border-slate-600">
                                          <span className="font-medium text-slate-800 dark:text-white">{s.productName}</span>
                                          <span className={`px-2 py-1 rounded text-xs font-bold ${s.suggestedAction.includes('Urgent') ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'}`}>
                                              {s.suggestedAction}
                                          </span>
                                      </div>
                                  ))
                              )}
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

    </div>
  );
}

export default Inventory;

import React, { useState, useRef, useEffect } from 'react';
import { Sale, ReturnTransaction, User, Customer } from '../types';
import { Search, Calendar, Filter, Eye, RotateCcw, CheckCircle, AlertTriangle, User as UserIcon, CreditCard, Banknote, Smartphone, Wallet, X, ChevronDown, TrendingUp, ShoppingBag, ArrowDownRight, DollarSign, Coins, FileText } from 'lucide-react';

interface SalesHistoryProps {
  sales: Sale[];
  returns: ReturnTransaction[];
  users: User[];
  customers: Customer[];
  currency: string;
}

const SalesHistory: React.FC<SalesHistoryProps> = ({ 
  sales, 
  returns, 
  users, 
  customers, 
  currency 
}) => {
  const [activeTab, setActiveTab] = useState<'SALES' | 'RETURNS'>('SALES');
  const [searchTerm, setSearchTerm] = useState('');

  // Date Range State
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [isDateFilterOpen, setIsDateFilterOpen] = useState(false);
  const dateFilterRef = useRef<HTMLDivElement>(null);

  const [statusFilter, setStatusFilter] = useState<'ALL' | 'COMPLETED' | 'RETURNED' | 'PARTIAL'>('ALL');
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };
  const symbol = getCurrencySymbol(currency);

  // Close filter dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dateFilterRef.current && !dateFilterRef.current.contains(event.target as Node)) {
        setIsDateFilterOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Date Presets Logic
  const applyDatePreset = (preset: 'TODAY' | 'YESTERDAY' | 'LAST_7' | 'LAST_30' | 'THIS_MONTH' | 'LAST_MONTH' | 'THIS_YEAR') => {
      const today = new Date();
      let start = new Date();
      let end = new Date();

      switch(preset) {
          case 'TODAY':
              // start/end are today
              break;
          case 'YESTERDAY':
              start.setDate(today.getDate() - 1);
              end.setDate(today.getDate() - 1);
              break;
          case 'LAST_7':
              start.setDate(today.getDate() - 7);
              break;
          case 'LAST_30':
              start.setDate(today.getDate() - 30);
              break;
          case 'THIS_MONTH':
              start = new Date(today.getFullYear(), today.getMonth(), 1);
              break;
          case 'LAST_MONTH':
              start = new Date(today.getFullYear(), today.getMonth() - 1, 1);
              end = new Date(today.getFullYear(), today.getMonth(), 0);
              break;
          case 'THIS_YEAR':
              start = new Date(today.getFullYear(), 0, 1);
              break;
      }

      setStartDate(start.toISOString().split('T')[0]);
      setEndDate(end.toISOString().split('T')[0]);
      setIsDateFilterOpen(false);
  };

  // Helper to check return status
  const getSaleStatus = (saleId: string) => {
    const saleReturns = returns.filter(r => r.originalSaleId === saleId);
    if (saleReturns.length === 0) return 'COMPLETED';

    // Check if fully returned
    const sale = sales.find(s => s.id === saleId);
    if (!sale) return 'COMPLETED';

    const totalSold = sale.items.reduce((sum, i) => sum + i.quantity, 0);
    const totalReturned = saleReturns.reduce((sum, r) => sum + r.items.reduce((riSum, ri) => riSum + ri.quantity, 0), 0);

    if (totalReturned >= totalSold) return 'RETURNED'; // Fully Returned
    return 'PARTIAL'; // Partially Returned
  };

  const filteredSales = sales.filter(sale => {
    // Search Filter
    const searchMatch = 
      sale.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (sale.customerName && sale.customerName.toLowerCase().includes(searchTerm.toLowerCase())) ||
      users.find(u => u.id === sale.cashierId)?.name.toLowerCase().includes(searchTerm.toLowerCase());

    // Date Range Filter
    let dateMatch = true;
    if (startDate || endDate) {
        const saleDate = new Date(sale.timestamp);
        saleDate.setHours(0,0,0,0);

        if (startDate) {
            const start = new Date(startDate);
            start.setHours(0,0,0,0);
            if (saleDate.getTime() < start.getTime()) dateMatch = false;
        }
        if (endDate) {
            const end = new Date(endDate);
            end.setHours(23,59,59,999);
            if (saleDate.getTime() > end.getTime()) dateMatch = false;
        }
    }

    // Status Filter
    let statusMatch = true;
    if (statusFilter !== 'ALL') {
        const status = getSaleStatus(sale.id);
        if (statusFilter === 'COMPLETED' && status !== 'COMPLETED') statusMatch = false;
        if (statusFilter === 'RETURNED' && status !== 'RETURNED') statusMatch = false;
        if (statusFilter === 'PARTIAL' && status !== 'PARTIAL') statusMatch = false;
    }

    return searchMatch && dateMatch && statusMatch;
  }).sort((a, b) => b.timestamp - a.timestamp);

  const filteredReturns = returns.filter(ret => {
      // Search Filter
      const sale = sales.find(s => s.id === ret.originalSaleId);
      const customerName = sale?.customerName || '';

      const searchMatch = 
        ret.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        ret.originalSaleId.toLowerCase().includes(searchTerm.toLowerCase()) ||
        customerName.toLowerCase().includes(searchTerm.toLowerCase());

      // Date Filter
      let dateMatch = true;
      if (startDate || endDate) {
          const retDate = new Date(ret.timestamp);
          retDate.setHours(0,0,0,0);
          if (startDate) {
              const start = new Date(startDate);
              start.setHours(0,0,0,0);
              if (retDate.getTime() < start.getTime()) dateMatch = false;
          }
          if (endDate) {
              const end = new Date(endDate);
              end.setHours(23,59,59,999);
              if (retDate.getTime() > end.getTime()) dateMatch = false;
          }
      }
      return searchMatch && dateMatch;
  }).sort((a, b) => b.timestamp - a.timestamp);

  // --- Summary Calculations ---
  const totalOrders = filteredSales.length;
  const grossSales = filteredSales.reduce((sum, s) => sum + s.totalAmount, 0);

  // Calculate refunds specifically linked to the filtered sales
  const filteredSaleIds = new Set(filteredSales.map(s => s.id));
  const relatedReturns = returns.filter(r => filteredSaleIds.has(r.originalSaleId));
  const totalRefunded = relatedReturns.reduce((sum, r) => sum + r.totalRefund, 0);

  const netSales = grossSales - totalRefunded;

  // Profit Calculations
  const grossProfit = filteredSales.reduce((sum, s) => sum + s.totalProfit, 0);

  // Calculate Profit Lost from Returns (Need to check original sale items for cost basis)
  const profitLost = relatedReturns.reduce((acc, ret) => {
      const originalSale = sales.find(s => s.id === ret.originalSaleId);
      if (!originalSale) return acc;

      const returnProfitLoss = ret.items.reduce((pLoss, rItem) => {
          const originalItem = originalSale.items.find(i => i.productId === rItem.productId);
          if (!originalItem) return pLoss;

          const unitProfit = originalItem.priceAtSale - originalItem.costAtSale;
          return pLoss + (unitProfit * rItem.quantity);
      }, 0);

      return acc + returnProfitLoss;
  }, 0);

  const netProfit = grossProfit - profitLost;


  const getPaymentIcon = (method: string) => {
      switch(method) {
          case 'CASH': return <Banknote size={14} className="mr-1"/>;
          case 'CARD': return <CreditCard size={14} className="mr-1"/>;
          case 'DIGITAL': return <Smartphone size={14} className="mr-1"/>;
          case 'STORE_CREDIT': return <Wallet size={14} className="mr-1"/>;
          default: return null;
      }
  };

  const getStatusBadge = (status: string) => {
      switch(status) {
          case 'COMPLETED': return (
              <span className="flex items-center text-xs font-bold bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 px-2 py-1 rounded">
                  <CheckCircle size={12} className="mr-1"/> Completed
              </span>
          );
          case 'RETURNED': return (
              <span className="flex items-center text-xs font-bold bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400 px-2 py-1 rounded">
                  <RotateCcw size={12} className="mr-1"/> Fully Returned
              </span>
          );
          case 'PARTIAL': return (
              <span className="flex items-center text-xs font-bold bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400 px-2 py-1 rounded">
                  <AlertTriangle size={12} className="mr-1"/> Partial Return
              </span>
          );
          default: return null;
      }
  };

  const saleReturns = selectedSale ? returns.filter(r => r.originalSaleId === selectedSale.id) : [];

  // Calculation for the modal
  const modalTotalRefunded = saleReturns.reduce((sum, r) => sum + r.totalRefund, 0);
  const modalNetTotal = selectedSale ? selectedSale.totalAmount - modalTotalRefunded : 0;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">History Logs</h2>
          <p className="text-slate-500 text-sm mt-1">View transaction logs, summaries, and detailed return information.</p>
        </div>
        <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
            <button 
                onClick={() => setActiveTab('SALES')}
                className={`px-4 py-2 text-sm font-medium rounded-md transition ${activeTab === 'SALES' ? 'bg-white dark:bg-slate-600 shadow text-blue-600 dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
            >
                Sales Log
            </button>
            <button 
                onClick={() => setActiveTab('RETURNS')}
                className={`px-4 py-2 text-sm font-medium rounded-md transition ${activeTab === 'RETURNS' ? 'bg-white dark:bg-slate-600 shadow text-red-600 dark:text-red-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
            >
                Returns Log
            </button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full">
            <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Search</label>
            <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder={activeTab === 'SALES' ? "Order ID, Customer, or Cashier..." : "Return ID, Order Ref, or Customer..."}
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400"
                />
            </div>
          </div>

          {/* Unified Date Range Picker */}
          <div className="relative w-full md:w-auto" ref={dateFilterRef}>
              <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Date Range</label>
              <button
                  onClick={() => setIsDateFilterOpen(!isDateFilterOpen)}
                  className="w-full md:w-64 px-4 py-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-slate-700 dark:text-slate-200 flex items-center justify-between hover:bg-slate-100 dark:hover:bg-slate-600 transition"
              >
                  <span className="text-sm flex items-center truncate">
                      <Calendar size={16} className="mr-2 text-slate-400 shrink-0"/>
                      {startDate && endDate ? `${new Date(startDate).toLocaleDateString()} - ${new Date(endDate).toLocaleDateString()}` : 
                       startDate ? `From ${new Date(startDate).toLocaleDateString()}` :
                       endDate ? `Until ${new Date(endDate).toLocaleDateString()}` :
                       'All Dates'}
                  </span>
                  <ChevronDown size={14} className="ml-2 text-slate-400 shrink-0" />
              </button>

              {isDateFilterOpen && (
                  <div className="absolute right-0 md:left-auto md:right-0 top-full mt-2 w-80 sm:w-96 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 z-30 p-4">
                      <div className="flex space-x-2 mb-4">
                          <div className="flex-1">
                              <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Start Date</label>
                              <input 
                                  type="date" 
                                  value={startDate}
                                  onChange={(e) => setStartDate(e.target.value)}
                                  max={endDate}
                                  className="w-full p-2 text-sm border rounded-lg bg-slate-50 dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:[color-scheme:dark]"
                              />
                          </div>
                          <div className="flex-1">
                              <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">End Date</label>
                              <input 
                                  type="date" 
                                  value={endDate}
                                  onChange={(e) => setEndDate(e.target.value)}
                                  min={startDate}
                                  className="w-full p-2 text-sm border rounded-lg bg-slate-50 dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:[color-scheme:dark]"
                              />
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-2 border-t border-slate-100 dark:border-slate-700 pt-3">
                           <button onClick={() => applyDatePreset('TODAY')} className="px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">Today</button>
                           <button onClick={() => applyDatePreset('YESTERDAY')} className="px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">Yesterday</button>
                           <button onClick={() => applyDatePreset('LAST_7')} className="px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">Last 7 Days</button>
                           <button onClick={() => applyDatePreset('LAST_30')} className="px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">Last 30 Days</button>
                           <button onClick={() => applyDatePreset('THIS_MONTH')} className="px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">This Month</button>
                           <button onClick={() => applyDatePreset('LAST_MONTH')} className="px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">Last Month</button>
                           <button onClick={() => applyDatePreset('THIS_YEAR')} className="col-span-2 px-2 py-1.5 text-xs text-center rounded bg-slate-50 dark:bg-slate-700/50 hover:bg-blue-50 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 hover:text-blue-600 transition">This Year</button>
                      </div>
                       <div className="mt-3 pt-3 border-t border-slate-100 dark:border-slate-700 flex justify-end items-center">
                          <button 
                              onClick={() => { setStartDate(''); setEndDate(''); }}
                              className="text-xs text-red-500 hover:underline mr-auto"
                          >
                              Reset Range
                          </button>
                          <button 
                              onClick={() => setIsDateFilterOpen(false)}
                              className="px-4 py-1.5 bg-blue-600 text-white text-xs font-bold rounded hover:bg-blue-700 transition"
                          >
                              Done
                          </button>
                       </div>
                  </div>
              )}
          </div>

          {activeTab === 'SALES' && (
              <div className="w-full md:w-48">
                  <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Status</label>
                  <div className="relative">
                      <Filter className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} />
                      <select 
                        value={statusFilter}
                        onChange={(e) => setStatusFilter(e.target.value as any)}
                        className="w-full pl-10 pr-8 py-2.5 rounded-lg border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 dark:bg-slate-700 dark:text-white appearance-none min-w-[150px]"
                      >
                          <option value="ALL">All Sales</option>
                          <option value="COMPLETED">Completed</option>
                          <option value="PARTIAL">Partial Return</option>
                          <option value="RETURNED">Fully Returned</option>
                      </select>
                  </div>
              </div>
          )}

