                      </button>
                      <button 
                        onClick={() => setActiveHistoryTab('RETURNS')}
                        className={`py-3 text-sm font-bold border-b-2 transition-colors ${activeHistoryTab === 'RETURNS' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
                      >
                          Return History
                      </button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-0">
                      {activeHistoryTab === 'STOCK' && (
                          getProductHistory(historyProduct.id).length === 0 ? (
                              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                  <History size={48} className="opacity-20 mb-4"/>
                                  <p className="font-medium">No stock history recorded.</p>
                              </div>
                          ) : (
                              <table className="w-full text-left text-sm border-collapse">
                                  <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                      <tr>
                                          <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                          <th className="p-4 border-b dark:border-slate-700">User</th>
                                          <th className="p-4 border-b dark:border-slate-700">Type</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Change</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-center">Stock</th>
                                          <th className="p-4 border-b dark:border-slate-700">Reason / Notes</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                      {getProductHistory(historyProduct.id).map(adj => (
                                          <tr key={adj.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                              <td className="p-4 text-slate-600 dark:text-slate-300">
                                                  <div className="font-medium">{new Date(adj.timestamp).toLocaleDateString()}</div>
                                                  <div className="text-xs text-slate-400">{new Date(adj.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                              </td>
                                              <td className="p-4">
                                                  <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                      <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                      {adj.userName.split(' ')[0]}
                                                  </div>
                                              </td>
                                              <td className="p-4">
                                                  <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                                      adj.type === 'ADD' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                                                      adj.type === 'REMOVE' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' :
                                                      'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                                                  }`}>
                                                      {adj.type}
                                                  </span>
                                              </td>
                                              <td className={`p-4 text-right font-bold ${
                                                  adj.type === 'ADD' ? 'text-green-600 dark:text-green-400' : 
                                                  adj.type === 'REMOVE' ? 'text-red-600 dark:text-red-400' : 
                                                  'text-blue-600 dark:text-blue-400'
                                              }`}>
                                                  {adj.type === 'ADD' ? '+' : adj.type === 'REMOVE' ? '-' : ''}{adj.quantity}
                                              </td>
                                              <td className="p-4 text-center">
                                                  <div className="flex items-center justify-center gap-2 text-xs">
                                                      <span className="text-slate-400 line-through">{adj.previousStock}</span>
                                                      <ArrowRight size={12} className="text-slate-300"/>
                                                      <span className="font-bold text-slate-800 dark:text-white bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">{adj.newStock}</span>
                                                  </div>
                                              </td>
                                              <td className="p-4 max-w-[200px]">
                                                  <div className="font-medium text-slate-800 dark:text-white truncate">{adj.reason}</div>
                                                  {adj.notes && <div className="text-xs text-slate-500 italic truncate">"{adj.notes}"</div>}
                                              </td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          )
                      )}

                      {activeHistoryTab === 'PRICE' && (
                          getProductPriceHistory(historyProduct.id).length === 0 ? (
                              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                  <Tag size={48} className="opacity-20 mb-4"/>
                                  <p className="font-medium">No price changes recorded.</p>
                              </div>
                          ) : (
                              <table className="w-full text-left text-sm border-collapse">
                                  <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                      <tr>
                                          <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                          <th className="p-4 border-b dark:border-slate-700">User</th>
                                          <th className="p-4 border-b dark:border-slate-700">Change Type</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Old Value</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">New Value</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Diff</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                      {getProductPriceHistory(historyProduct.id).map(log => {
                                          const diff = log.newValue - log.oldValue;
                                          const isIncrease = diff > 0;
                                          return (
                                              <tr key={log.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                                  <td className="p-4 text-slate-600 dark:text-slate-300">
                                                      <div className="font-medium">{new Date(log.timestamp).toLocaleDateString()}</div>
                                                      <div className="text-xs text-slate-400">{new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                                  </td>
                                                  <td className="p-4">
                                                      <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                          <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                          {log.userName.split(' ')[0]}
                                                      </div>
                                                  </td>
                                                  <td className="p-4">
                                                      <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${log.type === 'PRICE' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'}`}>
                                                          {log.type === 'PRICE' ? 'Selling Price' : 'Cost Price'}
                                                      </span>
                                                  </td>
                                                  <td className="p-4 text-right text-slate-500 font-mono">
                                                      {symbol}{log.oldValue.toFixed(2)}
                                                  </td>
                                                  <td className="p-4 text-right font-bold text-slate-800 dark:text-white font-mono">
                                                      {symbol}{log.newValue.toFixed(2)}
                                                  </td>
                                                  <td className="p-4 text-right">
                                                      <div className={`flex items-center justify-end font-bold text-xs ${isIncrease ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                                                          {isIncrease ? <TrendingUp size={14} className="mr-1"/> : <TrendingDown size={14} className="mr-1"/>}
                                                          {Math.abs((diff / log.oldValue) * 100).toFixed(1)}%
                                                      </div>
                                                  </td>
                                              </tr>
                                          );
                                      })}
                                  </tbody>
                              </table>
                          )
                      )}

                      {activeHistoryTab === 'RETURNS' && (
                          getProductReturnHistory(historyProduct.id).length === 0 ? (
                              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                  <RotateCcw size={48} className="opacity-20 mb-4"/>
                                  <p className="font-medium">No returns recorded for this product.</p>
                              </div>
                          ) : (
                              <table className="w-full text-left text-sm border-collapse">
                                  <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                      <tr>
                                          <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                          <th className="p-4 border-b dark:border-slate-700">Order Ref</th>
                                          <th className="p-4 border-b dark:border-slate-700">Customer</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-center">Qty Returned</th>
                                          <th className="p-4 border-b dark:border-slate-700">Condition / Reason</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-center">Restocked</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Refund Value</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                      {getProductReturnHistory(historyProduct.id).map(ret => {
                                          const item = ret.items.find(i => i.productId === historyProduct.id);
                                          if (!item) return null;
                                          const originalSale = sales.find(s => s.id === ret.originalSaleId);
                                          return (
                                              <tr key={ret.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                                  <td className="p-4 text-slate-600 dark:text-slate-300">
                                                      <div className="font-medium">{new Date(ret.timestamp).toLocaleDateString()}</div>
                                                      <div className="text-xs text-slate-400">{new Date(ret.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                                  </td>
                                                  <td className="p-4">
                                                      <div className="font-mono text-xs text-blue-600 dark:text-blue-400">
                                                          #{ret.originalSaleId.split('-')[1]}
                                                      </div>
                                                  </td>
                                                  <td className="p-4">
                                                      <div className="flex items-center text-slate-700 dark:text-slate-200 font-medium">
                                                          <UserIcon size={12} className="mr-1.5 text-slate-400"/>
                                                          {originalSale?.customerName || 'Guest'}
                                                      </div>
                                                  </td>
                                                  <td className="p-4 text-center font-bold text-red-600 dark:text-red-400">
                                                      {item.quantity}
                                                  </td>
                                                  <td className="p-4 max-w-[200px] text-slate-600 dark:text-slate-300">
                                                      {item.reason}
                                                  </td>
                                                  <td className="p-4 text-center">
                                                      {item.restock ? (
                                                          <span className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400">
                                                              YES
                                                          </span>
                                                      ) : (
                                                          <span className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 dark:bg-slate-700 dark:text-slate-400">
                                                              NO
                                                          </span>
                                                      )}
                                                  </td>
                                                  <td className="p-4 text-right font-medium text-slate-800 dark:text-white">
                                                      {symbol}{item.refundAmount.toFixed(2)}
                                                  </td>
                                              </tr>
                                          );
                                      })}
                                  </tbody>
                              </table>
                          )
                      )}
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl flex justify-end">
                      <button onClick={() => setIsHistoryOpen(false)} className="px-6 py-2 bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold rounded-lg hover:bg-slate-300 dark:hover:bg-slate-600 transition">Close</button>
                  </div>
              </div>
          </div>
      )}

      {/* AI Insights Modal */}
      {isInsightsOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-indigo-50 dark:bg-indigo-900/20 rounded-t-xl">
                      <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-300 flex items-center"><Sparkles className="mr-2" size={20}/> Inventory Intelligence</h3>
                      <button onClick={() => setIsInsightsOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={20}/></button>
                  </div>
                  <div className="p-6 overflow-y-auto flex-1">
                      {isLoadingSuggestions ? (
                          <div className="flex flex-col items-center justify-center py-12 text-slate-500">
                              <RefreshCw className="animate-spin mb-3" size={32}/>
                              <p>Analyzing inventory data...</p>
                          </div>
                      ) : (
                          <div className="space-y-4">
                              <h4 className="font-bold text-slate-800 dark:text-white border-b border-slate-100 dark:border-slate-700 pb-2">Restock Recommendations</h4>
                              {restockSuggestions.length === 0 ? (
                                  <p className="text-slate-500 italic">No urgent actions detected. Good job!</p>
                              ) : (
                                  restockSuggestions.map((s, idx) => (
                                      <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-200 dark:border-slate-600">
                                          <span className="font-medium text-slate-800 dark:text-white">{s.productName}</span>
                                          <span className={`px-2 py-1 rounded text-xs font-bold ${s.suggestedAction.includes('Urgent') ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'}`}>
                                              {s.suggestedAction}
                                          </span>
                                      </div>
                                  ))
                              )}
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

    </div>
  );
}

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Product, StockAdjustment, User, ReturnTransaction, Sale, Customer, PriceHistory, UserRole } from '../types';
import { Search, Plus, Filter, Package, AlertTriangle, Edit2, Trash2, Activity, ChevronDown, History, RefreshCw, Save, X, Sparkles, TrendingUp, DollarSign, FileText, ChevronRight, ArrowRight, User as UserIcon, Image as ImageIcon, Tag, TrendingDown, RotateCcw } from 'lucide-react';
import { generateProductDescription, suggestRestock } from '../services/geminiService';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

const Inventory: React.FC<InventoryProps> = ({
  products,
  setProducts,
  onAdjustStock,
  onBulkAdjustStock,
  currentUser,
  currency,
  showToast,
  stockAdjustments,
  onLogPriceChange,
  priceHistory,
  returns,
  sales
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Modals
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [isInsightsOpen, setIsInsightsOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [activeHistoryTab, setActiveHistoryTab] = useState<'STOCK' | 'PRICE' | 'RETURNS'>('STOCK');

  // Dropdown state for category input
  const [showCategoryDropdown, setShowCategoryDropdown] = useState(false);

  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [historyProduct, setHistoryProduct] = useState<Product | null>(null);

  // Forms
  const [productForm, setProductForm] = useState<Partial<Product>>({
    name: '', sku: '', category: '', price: 0, cost: 0, stock: 0, minStockLevel: 5, unit: 'pcs', description: '', imageUrl: '', stockExpiryDate: ''
  });

  const [adjForm, setAdjForm] = useState({
      quantity: 0,
      type: 'ADD' as 'ADD' | 'REMOVE' | 'SET',
      reason: '',
      notes: ''
  });

  // AI State
  const [isGeneratingDesc, setIsGeneratingDesc] = useState(false);
  const [restockSuggestions, setRestockSuggestions] = useState<any[]>([]);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(false);

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };
  const symbol = getCurrencySymbol(currency);

  const categories = ['All', ...Array.from(new Set(products.map(p => p.category))) as string[]];
  const inputSuggestions = categories.filter(c => c !== 'All').sort();

  const filteredProducts = products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || p.sku.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCategory = categoryFilter === 'All' || p.category === categoryFilter;
      return matchSearch && matchCategory;
  });

  const handleOpenModal = (product?: Product) => {
      if (product) {
          setEditingProduct(product);
          setProductForm(product);
      } else {
          setEditingProduct(null);
          setProductForm({ name: '', sku: '', category: 'General', price: 0, cost: 0, stock: 0, minStockLevel: 5, unit: 'pcs', description: '', imageUrl: '', stockExpiryDate: '' });
      }
      setIsProductModalOpen(true);
      setShowCategoryDropdown(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProductForm(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = () => {
      if (!productForm.name || !productForm.sku || productForm.price === undefined) {
          showToast("Name, SKU, and Price are required.", 'ERROR');
          return;
      }

      if (editingProduct) {
          // Check for price change to log history
          if (editingProduct.price !== productForm.price) {
              onLogPriceChange({
                  id: `ph-${Date.now()}`,
                  productId: editingProduct.id,
                  type: 'PRICE',
                  oldValue: editingProduct.price,
                  newValue: productForm.price!,
                  userId: currentUser.id,
                  userName: currentUser.name,
                  timestamp: Date.now()
              });
          }
          if (editingProduct.cost !== productForm.cost) {
              onLogPriceChange({
                  id: `ph-${Date.now()}-c`,
                  productId: editingProduct.id,
                  type: 'COST',
                  oldValue: editingProduct.cost,
                  newValue: productForm.cost!,
                  userId: currentUser.id,
                  userName: currentUser.name,
                  timestamp: Date.now()
              });
          }

          setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...productForm } as Product : p));
          showToast("Product updated successfully.", 'SUCCESS');
      } else {
          const newProduct: Product = {
              id: `p-${Date.now()}`,
              ...productForm as Product
          };
          setProducts(prev => [...prev, newProduct]);
          showToast("Product created successfully.", 'SUCCESS');
      }
      setIsProductModalOpen(false);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Are you sure you want to delete this product?")) {
          setProducts(prev => prev.filter(p => p.id !== id));
          showToast("Product deleted.", 'INFO');
      }
  };

  const handleOpenAdjModal = (product: Product) => {
      setSelectedProduct(product);
      setAdjForm({ quantity: 0, type: 'ADD', reason: '', notes: '' });
      setIsAdjModalOpen(true);
  };

  const handleOpenHistory = (product: Product) => {
      setHistoryProduct(product);
      setActiveHistoryTab('STOCK');
      setIsHistoryOpen(true);
  };

  const handleSubmitAdjustment = () => {
      if (!selectedProduct || adjForm.quantity < 0) return; // Allow 0 for SET, but usually checks > 0

      let newStock = selectedProduct.stock;
      if (adjForm.type === 'ADD') newStock += adjForm.quantity;
      if (adjForm.type === 'REMOVE') newStock = Math.max(0, newStock - adjForm.quantity);
      if (adjForm.type === 'SET') newStock = adjForm.quantity;

      onAdjustStock({
          id: `adj-${Date.now()}`,
          productId: selectedProduct.id,
          productName: selectedProduct.name,
          userId: currentUser.id,
          userName: currentUser.name,
          timestamp: Date.now(),
          type: adjForm.type,
          quantity: adjForm.quantity,
          previousStock: selectedProduct.stock,
          newStock,
          reason: adjForm.reason || 'Manual Adjustment',
          notes: adjForm.notes
      });
      setIsAdjModalOpen(false);
  };

  const handleGenerateDescription = async () => {
      if (!productForm.name || !productForm.category) {
          showToast("Please enter product name and category first.", 'ERROR');
          return;
      }
      setIsGeneratingDesc(true);
      const desc = await generateProductDescription(productForm.name, productForm.category);
      setProductForm(prev => ({ ...prev, description: desc }));
      setIsGeneratingDesc(false);
  };

  const handleOpenInsights = async () => {
      setIsInsightsOpen(true);
      setIsLoadingSuggestions(true);
      const suggestions = await suggestRestock(products);
      setRestockSuggestions(suggestions);
      setIsLoadingSuggestions(false);
  };

  const getProductHistory = (productId: string) => {
      return stockAdjustments
          .filter(a => a.productId === productId)
          .sort((a, b) => b.timestamp - a.timestamp);
  };

  const getProductPriceHistory = (productId: string) => {
      return priceHistory
          .filter(h => h.productId === productId)
          .sort((a, b) => b.timestamp - a.timestamp);
  };

  const getProductReturnHistory = (productId: string) => {
      return returns
          .filter(r => r.items.some(i => i.productId === productId))
          .sort((a, b) => b.timestamp - a.timestamp);
  };

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">Inventory</h2>
          <p className="text-slate-500 text-sm mt-1">Manage products, stock levels, and pricing.</p>
        </div>
        <div className="flex space-x-2">
            <button 
              onClick={handleOpenInsights}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg flex items-center transition shadow-sm"
            >
              <Sparkles size={18} className="mr-2" /> AI Insights
            </button>
            <button 
              onClick={() => handleOpenModal()}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center transition shadow-sm"
            >
              <Plus size={18} className="mr-2" /> Add Product
            </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row gap-4 items-center">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="Search products..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400"
            />
          </div>
          <div className="flex items-center space-x-2 w-full md:w-auto">
              <Filter className="text-slate-400" size={20} />
              <select 
                value={categoryFilter}
                onChange={(e) => setCategoryFilter(e.target.value)}
                className="w-full md:w-48 p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white outline-none"
              >
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
          </div>
      </div>

