                          <button onClick={() => setIsBulkPrintOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={24} /></button>
                      </div>
                  </div>

                  <div className="flex-1 overflow-y-auto bg-slate-100 p-8">
                      <div id="print-area" className="bg-white w-full min-h-full p-4 grid grid-cols-3 gap-4 shadow-lg mx-auto max-w-[210mm]">
