                  <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-lg">
                              <History size={20}/>
                          </div>
                          <div>
                              <h3 className="font-bold text-lg text-slate-800 dark:text-white">Product History</h3>
                              <p className="text-xs text-slate-500 dark:text-slate-400">{historyProduct.name} ({historyProduct.sku})</p>
                          </div>
                      </div>
                      <button onClick={() => setIsHistoryOpen(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors text-slate-400"><X size={20}/></button>
