                          Price History
                      </button>
                      <button 
                        onClick={() => setActiveHistoryTab('RETURNS')}
                        className={`py-3 text-sm font-bold border-b-2 transition-colors ${activeHistoryTab === 'RETURNS' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'}`}
