                          Return History
                      </button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-0">
                      {activeHistoryTab === 'STOCK' && (
                          getProductHistory(historyProduct.id).length === 0 ? (
                              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                  <History size={48} className="opacity-20 mb-4"/>
                                  <p className="font-medium">No stock history recorded.</p>
                              </div>
                          ) : (
                              <table className="w-full text-left text-sm border-collapse">
                                  <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase sticky top-0 shadow-sm">
                                      <tr>
                                          <th className="p-4 border-b dark:border-slate-700">Date & Time</th>
                                          <th className="p-4 border-b dark:border-slate-700">User</th>
                                          <th className="p-4 border-b dark:border-slate-700">Type</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Change</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-center">Stock</th>
                                          <th className="p-4 border-b dark:border-slate-700">Reason / Notes</th>
