            id: item.productId,
            qty: returnableMap[item.productId],
            restock: true,
            reason: 'Mass Return'
        }));
      if (returnItemsState.length === allItemsWithQty.length) setReturnItemsState([]);
      else setReturnItemsState(allItemsWithQty);
  };

  const updateReturnQty = (productId: string, qty: number) => {
