                                          <tr key={adj.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                              <td className="p-4 text-slate-600 dark:text-slate-300">
                                                  <div className="font-medium">{new Date(adj.timestamp).toLocaleDateString()}</div>
                                                  <div className="text-xs text-slate-400">{new Date(adj.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
