                                          <th className="p-4 border-b dark:border-slate-700 text-center">Qty Returned</th>
                                          <th className="p-4 border-b dark:border-slate-700">Condition / Reason</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-center">Restocked</th>
                                          <th className="p-4 border-b dark:border-slate-700 text-right">Refund Value</th>
