// Simple Barcode Component for Labels
const LabelBarcode = ({ value }: { value: string }) => {
    // Deterministic visual representation based on string hash
    const bars = [];
    let hash = 0;
    for (let i = 0; i < value.length; i++) {
        hash = ((hash << 5) - hash) + value.charCodeAt(i);
        hash |= 0;
    }
    const seededRandom = () => {
        const x = Math.sin(hash++) * 10000;
        return x - Math.floor(x);
    };
    // Generate 25 bars
    for(let i=0; i<25; i++) {
        const r = seededRandom();
        let w = 4; 
        if (r > 0.7) w = 8;
        else if (r < 0.3) w = 2;
        bars.push(w);
    }
    return (
        <div className="flex flex-col items-center justify-center w-full">
            <div className="flex justify-center h-8 overflow-hidden">
                {bars.map((w, i) => (
                    <div key={i} style={{ 
                        width: `${w}px`, 
                        height: '100%', 
                        backgroundColor: 'black', 
                        marginLeft: '1px', 
                        marginRight: '1px' 
                    }}></div>
                ))}
            </div>
            <div className="text-[10px] font-mono tracking-widest uppercase mt-0.5">{value}</div>
        </div>
    );
};

