                                    </button>
                                </td>
                                <td onClick={() => handleViewDetails(product)} className="p-4 cursor-pointer">
                                    <div className="flex items-center">
                                        <div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden shrink-0">
