                      id: `ph-bulk-${Date.now()}-${p.id}`,
                      productId: p.id,
                      type: 'PRICE',
                      oldValue: p.price,
                      newValue: updated.price,
                      userId: currentUser.id,
                      userName: currentUser.name,
                      timestamp: Date.now()
