                              <span className="ml-2 text-sm text-slate-500">%</span>
                          </div>
                          <p className="text-[10px] text-slate-400 mt-1">Example: '10' increases price by 10%. '-5' decreases by 5%.</p>
                      </div>
                  </div>

                  <div className="flex justify-end space-x-3 mt-6">
                      <button onClick={() => setIsBulkEditOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">Cancel</button>
                      <button onClick={handleBulkEditSubmit} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg shadow-md hover:bg-blue-700">Apply Changes</button>
                  </div>
              </div>
          </div>
      )}

      {/* Bulk Print Labels Modal */}
      {isBulkPrintOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-4xl h-[85vh] flex flex-col animate-in zoom-in-95 duration-200">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                      <h3 className="font-bold text-slate-800 dark:text-white flex items-center"><Printer className="mr-2" size={20}/> Print Barcode Labels</h3>
                      <div className="flex gap-2">
                          <button onClick={handlePrintLabels} className="bg-blue-600 text-white px-4 py-1.5 rounded-lg text-sm font-bold shadow hover:bg-blue-700 transition">Print Now</button>
                          <button onClick={() => setIsBulkPrintOpen(false)}><X className="text-slate-400 hover:text-slate-600" size={24} /></button>
                      </div>
                  </div>

                  <div className="flex-1 overflow-y-auto bg-slate-100 dark:bg-slate-900 p-8">
                      <div id="print-area" className="bg-white text-black w-full min-h-full p-4 grid grid-cols-3 gap-4 shadow-lg mx-auto max-w-[210mm]">
                          {products.filter(p => selectedIds.has(p.id)).map(product => (
                              <div key={product.id} className="label-item border border-dashed border-slate-300 p-4 flex flex-col items-center justify-center text-center h-[140px] rounded-lg bg-white">
                                  <div className="font-bold text-sm mb-1 truncate w-full px-2 text-black">{product.name}</div>
                                  <div className="font-black text-lg mb-1 text-black">{symbol}{product.price.toFixed(2)}</div>
                                  <LabelBarcode value={product.barcode || product.sku} />
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Stock Adjustment Modal */}
      {isAdjModalOpen && selectedProduct && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6 animate-in zoom-in-95 duration-200">
                  <h3 className="text-lg font-bold mb-4 text-slate-800 dark:text-white">Adjust Stock: {selectedProduct.name}</h3>
                  <div className="bg-slate-100 dark:bg-slate-700 p-3 rounded-lg mb-4 text-center">
                      <span className="block text-xs text-slate-500 dark:text-slate-400 uppercase font-bold">Current Stock</span>
                      <span className="text-2xl font-black text-slate-800 dark:text-white">{selectedProduct.stock} {selectedProduct.unit}</span>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Action</label>
                          <div className="flex space-x-2">
                              <button onClick={() => setAdjForm({...adjForm, type: 'ADD'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'ADD' ? 'bg-green-100 border-green-200 text-green-700 dark:bg-green-900/30 dark:border-green-800 dark:text-green-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>ADD</button>
                              <button onClick={() => setAdjForm({...adjForm, type: 'REMOVE'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'REMOVE' ? 'bg-red-100 border-red-200 text-red-700 dark:bg-red-900/30 dark:border-red-800 dark:text-red-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>REMOVE</button>
                              <button onClick={() => setAdjForm({...adjForm, type: 'SET'})} className={`flex-1 py-2 text-xs font-bold rounded border ${adjForm.type === 'SET' ? 'bg-blue-100 border-blue-200 text-blue-700 dark:bg-blue-900/30 dark:border-blue-800 dark:text-blue-400' : 'dark:border-slate-600 dark:text-slate-300'}`}>SET</button>
                          </div>
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Quantity</label>
                          <input type="number" min="0" value={adjForm.quantity} onChange={e => setAdjForm({...adjForm, quantity: parseInt(e.target.value)})} className={`text-lg font-bold text-center ${inputClass}`} />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Reason</label>
                          <input type="text" value={adjForm.reason} onChange={e => setAdjForm({...adjForm, reason: e.target.value})} className={inputClass} placeholder="e.g. Damage, Restock, Count" />
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1">Notes</label>
                          <input type="text" value={adjForm.notes} onChange={e => setAdjForm({...adjForm, notes: e.target.value})} className={inputClass} placeholder="Optional details..." />
                      </div>
                  </div>
                  <div className="flex justify-end space-x-3 mt-6">
                      <button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg">Cancel</button>
                      <button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-slate-900 dark:bg-blue-600 text-white font-bold rounded-lg shadow-md">Confirm</button>
                  </div>
              </div>
          </div>
      )}

    </div>
  );
}

export default Inventory;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sale, ReturnTransaction, User, Customer } from '../types';
import { Search, Calendar, Filter, Eye, RotateCcw, CheckCircle, AlertTriangle, User as UserIcon, CreditCard, Banknote, Smartphone, Wallet, X, ChevronDown, TrendingUp, ShoppingBag, ArrowDownRight, DollarSign, Coins, FileText, Download } from 'lucide-react';

interface SalesHistoryProps {
  sales: Sale[];
  returns: ReturnTransaction[];
  users: User[];
  customers: Customer[];
  currency: string;
}

const SalesHistory: React.FC<SalesHistoryProps> = ({ 
  sales, 
  returns, 
  users, 
  customers, 
  currency 
}) => {
  const [activeTab, setActiveTab] = useState<'SALES' | 'RETURNS'>('SALES');
  const [searchTerm, setSearchTerm] = useState('');

  // Date Range State
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [isDateFilterOpen, setIsDateFilterOpen] = useState(false);
  const dateFilterRef = useRef<HTMLDivElement>(null);

  const [statusFilter, setStatusFilter] = useState<'ALL' | 'COMPLETED' | 'RETURNED' | 'PARTIAL'>('ALL');
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };
  const symbol = getCurrencySymbol(currency);

  // Close filter dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dateFilterRef.current && !dateFilterRef.current.contains(event.target as Node)) {
        setIsDateFilterOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Date Presets Logic
  const applyDatePreset = (preset: 'TODAY' | 'YESTERDAY' | 'LAST_7' | 'LAST_30' | 'THIS_MONTH' | 'LAST_MONTH' | 'THIS_YEAR') => {
      const today = new Date();
      let start = new Date();
      let end = new Date();

      switch(preset) {
          case 'TODAY':
              // start/end are today
              break;
          case 'YESTERDAY':
              start.setDate(today.getDate() - 1);
              end.setDate(today.getDate() - 1);
              break;
          case 'LAST_7':
              start.setDate(today.getDate() - 7);
              break;
          case 'LAST_30':
              start.setDate(today.getDate() - 30);
              break;
          case 'THIS_MONTH':
              start = new Date(today.getFullYear(), today.getMonth(), 1);
              break;
          case 'LAST_MONTH':
              start = new Date(today.getFullYear(), today.getMonth() - 1, 1);
              end = new Date(today.getFullYear(), today.getMonth(), 0);
              break;
          case 'THIS_YEAR':
              start = new Date(today.getFullYear(), 0, 1);
              break;
      }

      setStartDate(start.toISOString().split('T')[0]);
      setEndDate(end.toISOString().split('T')[0]);
      setIsDateFilterOpen(false);
  };

  // Helper to check return status
  const getSaleStatus = (saleId: string) => {
    const saleReturns = returns.filter(r => r.originalSaleId === saleId);
    if (saleReturns.length === 0) return 'COMPLETED';

    // Check if fully returned
    const sale = sales.find(s => s.id === saleId);
    if (!sale) return 'COMPLETED';

    const totalSold = sale.items.reduce((sum, i) => sum + i.quantity, 0);
    const totalReturned = saleReturns.reduce((sum, r) => sum + r.items.reduce((riSum, ri) => riSum + ri.quantity, 0), 0);

    if (totalReturned >= totalSold) return 'RETURNED'; // Fully Returned
    return 'PARTIAL'; // Partially Returned
  };

  const filteredSales = useMemo(() => {
    return sales.filter(sale => {
        // Search Filter
        const searchMatch = 
          sale.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          (sale.customerName && sale.customerName.toLowerCase().includes(searchTerm.toLowerCase())) ||
          users.find(u => u.id === sale.cashierId)?.name.toLowerCase().includes(searchTerm.toLowerCase());

        // Date Range Filter
        let dateMatch = true;
        if (startDate || endDate) {
            const saleDate = new Date(sale.timestamp);
            saleDate.setHours(0,0,0,0);

            if (startDate) {
                const start = new Date(startDate);
                start.setHours(0,0,0,0);
                if (saleDate.getTime() < start.getTime()) dateMatch = false;
            }
            if (endDate) {
                const end = new Date(endDate);
                end.setHours(23,59,59,999);
                if (saleDate.getTime() > end.getTime()) dateMatch = false;
            }
        }

        // Status Filter
        let statusMatch = true;
        if (statusFilter !== 'ALL') {
            const status = getSaleStatus(sale.id);
            if (statusFilter === 'COMPLETED' && status !== 'COMPLETED') statusMatch = false;
            if (statusFilter === 'RETURNED' && status !== 'RETURNED') statusMatch = false;
            if (statusFilter === 'PARTIAL' && status !== 'PARTIAL') statusMatch = false;
        }

        return searchMatch && dateMatch && statusMatch;
    }).sort((a, b) => b.timestamp - a.timestamp);
  }, [sales, searchTerm, startDate, endDate, statusFilter, users, returns]);

  const filteredReturns = useMemo(() => {
      return returns.filter(ret => {
          // Search Filter
          const sale = sales.find(s => s.id === ret.originalSaleId);
          const customerName = sale?.customerName || '';

          const searchMatch = 
            ret.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
            ret.originalSaleId.toLowerCase().includes(searchTerm.toLowerCase()) ||
            customerName.toLowerCase().includes(searchTerm.toLowerCase());

          // Date Filter
          let dateMatch = true;
          if (startDate || endDate) {
              const retDate = new Date(ret.timestamp);
              retDate.setHours(0,0,0,0);
              if (startDate) {
                  const start = new Date(startDate);
                  start.setHours(0,0,0,0);
                  if (retDate.getTime() < start.getTime()) dateMatch = false;
              }
              if (endDate) {
                  const end = new Date(endDate);
                  end.setHours(23,59,59,999);
                  if (retDate.getTime() > end.getTime()) dateMatch = false;
              }
          }
          return searchMatch && dateMatch;
      }).sort((a, b) => b.timestamp - a.timestamp);
  }, [returns, sales, searchTerm, startDate, endDate]);

  // --- Summary Calculations ---
  const totalOrders = filteredSales.length;
  const grossSales = filteredSales.reduce((sum, s) => sum + s.totalAmount, 0);

  // Calculate refunds specifically linked to the filtered sales
  const filteredSaleIds = new Set(filteredSales.map(s => s.id));
  const relatedReturns = returns.filter(r => filteredSaleIds.has(r.originalSaleId));
  const totalRefunded = relatedReturns.reduce((sum, r) => sum + r.totalRefund, 0);

  const netSales = grossSales - totalRefunded;

  // Profit Calculations
  const grossProfit = filteredSales.reduce((sum, s) => sum + s.totalProfit, 0);

  // Calculate Profit Lost from Returns (Need to check original sale items for cost basis)
  const profitLost = relatedReturns.reduce((acc, ret) => {
      const originalSale = sales.find(s => s.id === ret.originalSaleId);
      if (!originalSale) return acc;

      const returnProfitLoss = ret.items.reduce((pLoss, rItem) => {
          const originalItem = originalSale.items.find(i => i.productId === rItem.productId);
          if (!originalItem) return pLoss;

          const unitProfit = originalItem.priceAtSale - originalItem.costAtSale;
          return pLoss + (unitProfit * rItem.quantity);
      }, 0);

      return acc + returnProfitLoss;
  }, 0);

  const netProfit = grossProfit - profitLost;

  // --- Export Logic ---
  const handleExportSales = () => {
      let tableContent = `
          <tr style="height: 40px;"><td colspan="15" style="font-size: 16px; font-weight: bold; background-color: #e2e8f0; text-align: center; vertical-align: middle;">Detailed Sales Report - ${new Date().toLocaleDateString()}</td></tr>
          <tr><td colspan="15"></td></tr>
          <tr>
              <td colspan="3" style="font-weight: bold;">Date Range: ${startDate || 'Start'} to ${endDate || 'Present'}</td>
              <td colspan="3" style="font-weight: bold;">Total Orders: ${totalOrders}</td>
              <td colspan="3" style="font-weight: bold;">Gross Sales: ${currency} ${grossSales.toFixed(2)}</td>
              <td colspan="3" style="font-weight: bold;">Net Sales: ${currency} ${netSales.toFixed(2)}</td>
              <td colspan="3" style="font-weight: bold;">Net Profit: ${currency} ${netProfit.toFixed(2)}</td>
          </tr>
          <tr><td colspan="15"></td></tr>
          <tr style="background-color: #1e293b; color: white; font-weight: bold;">
              <th style="padding: 10px; border: 1px solid #ccc;">Sale ID</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Date</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Time</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Customer</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Type</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Cashier</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Payment</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Items Summary</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Subtotal</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Tax</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Total Amount</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Refunded</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Net Amount</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Profit</th>
              <th style="padding: 10px; border: 1px solid #ccc;">Status</th>
          </tr>
      `;

      filteredSales.forEach(sale => {
          // Find specific refunds for this sale
          const thisSaleReturns = returns.filter(r => r.originalSaleId === sale.id);
          const thisSaleRefunded = thisSaleReturns.reduce((sum, r) => sum + r.totalRefund, 0);

          // Calculate specific profit loss
          const thisSaleProfitLost = thisSaleReturns.reduce((acc, ret) => {
              return acc + ret.items.reduce((loss, rItem) => {
                  const origItem = sale.items.find(i => i.productId === rItem.productId);
                  if (!origItem) return loss;
                  return loss + ((origItem.priceAtSale - origItem.costAtSale) * rItem.quantity);
              }, 0);
          }, 0);

          const thisNetProfit = sale.totalProfit - thisSaleProfitLost;
          const status = getSaleStatus(sale.id);
          const statusColor = status === 'COMPLETED' ? '#f0fdf4' : status === 'RETURNED' ? '#fef2f2' : '#fffbeb';
          const itemsSummary = sale.items.map(i => `${i.productName} (x${i.quantity})`).join(', ');
          const customer = customers.find(c => c.id === sale.customerId);
          const customerType = customer ? (customer.type === 'MEMBER' ? 'Member' : 'Walk-in') : 'Walk-in';
          const cashierName = users.find(u => u.id === sale.cashierId)?.name || 'Unknown';

          tableContent += `
              <tr style="background-color: ${statusColor};">
                  <td style="border: 1px solid #ccc; mso-number-format:'@'">${sale.id.split('-')[1]}</td>
                  <td style="border: 1px solid #ccc;">${new Date(sale.timestamp).toLocaleDateString()}</td>
                  <td style="border: 1px solid #ccc;">${new Date(sale.timestamp).toLocaleTimeString()}</td>
                  <td style="border: 1px solid #ccc;">${sale.customerName || 'Guest'}</td>
                  <td style="border: 1px solid #ccc;">${customerType}</td>
                  <td style="border: 1px solid #ccc;">${cashierName}</td>
                  <td style="border: 1px solid #ccc;">${sale.paymentMethod}</td>
                  <td style="border: 1px solid #ccc;">${itemsSummary}</td>
                  <td style="border: 1px solid #ccc;">${sale.subTotal.toFixed(2)}</td>
                  <td style="border: 1px solid #ccc;">${sale.totalTax.toFixed(2)}</td>
                  <td style="border: 1px solid #ccc; font-weight: bold;">${sale.totalAmount.toFixed(2)}</td>
                  <td style="border: 1px solid #ccc; color: #dc2626;">${thisSaleRefunded > 0 ? '-' + thisSaleRefunded.toFixed(2) : '0.00'}</td>
                  <td style="border: 1px solid #ccc; font-weight: bold;">${(sale.totalAmount - thisSaleRefunded).toFixed(2)}</td>
                  <td style="border: 1px solid #ccc;">${thisNetProfit.toFixed(2)}</td>
                  <td style="border: 1px solid #ccc;">${status}</td>
              </tr>
          `;
      });

      const fullTemplate = `
          <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
          <head>
              <!--[if gte mso 9]>
              <xml>
                  <x:ExcelWorkbook>
                      <x:ExcelWorksheets>
                          <x:ExcelWorksheet>
                              <x:Name>Sales Export</x:Name>
                              <x:WorksheetOptions>
                                  <x:DisplayGridlines/>
                              </x:WorksheetOptions>
                          </x:ExcelWorksheet>
                      </x:ExcelWorksheets>
                  </x:ExcelWorkbook>
              </xml>
              <![endif]-->
              <meta http-equiv="content-type" content="text/plain; charset=UTF-8"/>
          </head>
          <body>
              <table>${tableContent}</table>
          </body>
          </html>
      `;

      const blob = new Blob([fullTemplate], { type: 'application/vnd.ms-excel' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Sales_Report_${new Date().toISOString().split('T')[0]}.xls`;
      a.click();
      window.URL.revokeObjectURL(url);
  };

  const getPaymentIcon = (method: string) => {
      switch(method) {
          case 'CASH': return <Banknote size={14} className="mr-1"/>;
          case 'CARD': return <CreditCard size={14} className="mr-1"/>;
          case 'DIGITAL': return <Smartphone size={14} className="mr-1"/>;
          case 'STORE_CREDIT': return <Wallet size={14} className="mr-1"/>;
          default: return null;
      }
  };

  const getStatusBadge = (status: string) => {
      switch(status) {
          case 'COMPLETED': return (
              <span className="flex items-center text-xs font-bold bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 px-2 py-1 rounded">
                  <CheckCircle size={12} className="mr-1"/> Completed
              </span>
          );
          case 'RETURNED': return (
              <span className="flex items-center text-xs font-bold bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400 px-2 py-1 rounded">
                  <RotateCcw size={12} className="mr-1"/> Fully Returned
              </span>
          );
          case 'PARTIAL': return (
              <span className="flex items-center text-xs font-bold bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400 px-2 py-1 rounded">
